package com.tommyknight.unachievements;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class UnachievementsPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(UnachievementsPlugin.class);
		RuneLite.main(args);
	}
}

package com.tommyknight.unachievements;

import lombok.Value;

/**
 * A game event flattened into something tasks can match against. The plugin owns every
 * {@code @Subscribe} handler and translates RuneLite events into these, so adding a task never
 * means adding another subscription.
 *
 * <p>{@code text} and {@code value} carry different things per type, documented on
 * {@link TaskEventType}. Unused fields are "" and 0.
 */
@Value
public class TaskEvent
{
	TaskEventType type;
	String text;
	int value;

	public static TaskEvent of(TaskEventType type)
	{
		return new TaskEvent(type, "", 0);
	}

	public static TaskEvent of(TaskEventType type, String text)
	{
		return new TaskEvent(type, text == null ? "" : text, 0);
	}

	public static TaskEvent of(TaskEventType type, int value)
	{
		return new TaskEvent(type, "", value);
	}
}

package com.tommyknight.unachievements;

import com.google.common.collect.ImmutableSet;
import java.util.Set;
import java.util.function.Predicate;
import javax.annotation.Nullable;
import lombok.Getter;

/**
 * One entry in Unachievements: a counter that levels from 1 to 99.
 *
 * <p>Each task declares exactly one tuning number. In {@link Mode#XP} that is the base experience
 * per action, multiplied by the tier the task currently sits at. In {@link Mode#LINEAR} it is the
 * number of actions that reaches 99, and the level is a straight fraction of it.
 *
 * <p>Linear exists for bounded tasks. Spreading thirty emotes across an exponential curve puts
 * the first emote somewhere around level 64; a fraction of the target puts it at level 4, which
 * is what a collection should feel like.
 */
@Getter
public class Task
{
	public enum Mode
	{
		/** Unbounded. Level comes from accumulated experience. */
		XP,
		/** Bounded. Level is a fraction of a known target. */
		LINEAR
	}

	/** Stable key used in saved config. Never change one without a migration. */
	private final String id;

	private final String name;

	/** What the task asks for, stated plainly. Shown in the sidebar under the name. */
	private final String description;

	/**
	 * Past participle phrase, e.g. "spun the camera". Slotted into "You have ... 10 times", so it
	 * must be the participle ("run out of energy") and not the past simple ("ran out of energy").
	 */
	private final String resultVerb;

	/**
	 * Singular noun the count is measured in, e.g. "time". Pluralised automatically. In a multi
	 * word unit the head noun is not always the last word, so a {@code *} may mark it:
	 * "tile* barefoot" gives "tiles barefoot", not "tile barefoots".
	 */
	private final String resultUnit;

	/** Whole sentence for a count of zero, where the participle form reads badly. */
	private final String neverText;

	private final Mode mode;

	/** Base xp per action in XP mode, or the action count that reaches 99 in LINEAR mode. */
	private final int tuning;

	/** Counts distinct event values rather than events. Storage becomes a bitset. */
	private final boolean unique;

	/**
	 * Counts the event's value rather than the event. Damage Taken uses this: one hitsplat for 27
	 * should move it by 27, where Ouch counts the same hitsplat as one.
	 */
	private final boolean weighted;

	/**
	 * Caps this task at one count per game tick when its trigger is spammable. Off only for tasks
	 * whose whole point is the raw click rate.
	 */
	private final boolean throttled;

	private final TaskEventType trigger;

	/** Extra condition on top of the trigger type. Null means every event of that type counts. */
	@Nullable
	private final Predicate<TaskEvent> filter;

	public Task(String id, String name, String description, String resultVerb, String resultUnit,
		String neverText, Mode mode, int tuning, boolean unique, boolean weighted, boolean throttled,
		TaskEventType trigger, @Nullable Predicate<TaskEvent> filter)
	{
		if (tuning <= 0)
		{
			throw new IllegalArgumentException("Task " + id + " needs a positive tuning value");
		}
		this.id = id;
		this.name = name;
		this.description = description;
		this.resultVerb = resultVerb;
		this.resultUnit = resultUnit;
		this.neverText = neverText;
		this.mode = mode;
		this.tuning = tuning;
		this.unique = unique;
		this.weighted = weighted;
		this.throttled = throttled;
		this.trigger = trigger;
		this.filter = filter;
	}

	/** How much one event moves the count by. */
	public int incrementFor(TaskEvent event)
	{
		return weighted ? Math.max(0, event.getValue()) : 1;
	}

	public boolean matches(TaskEvent event)
	{
		return event.getType() == trigger && (filter == null || filter.test(event));
	}

	/** Experience one action is worth right now. Zero in linear mode, which does not use xp. */
	public int xpFor(Tier currentTier)
	{
		if (mode != Mode.XP)
		{
			return 0;
		}
		return Math.max(1, Math.round(tuning * currentTier.getXpMultiplier()));
	}

	public int levelFor(int count, long xp)
	{
		if (mode == Mode.LINEAR)
		{
			if (count <= 0)
			{
				return 1;
			}
			long level = 1 + (98L * count) / tuning;
			return (int) Math.min(XpTable.MAX_LEVEL, level);
		}
		return XpTable.levelForXp(xp);
	}

	/** Fill of the row's progress bar: how far through the current level, 0 to 1. */
	public float progressFor(int count, long xp)
	{
		if (mode == Mode.LINEAR)
		{
			int level = levelFor(count, xp);
			if (level >= XpTable.MAX_LEVEL)
			{
				return 1f;
			}
			// Actions per level, as a fraction of the way to the next one.
			float perLevel = tuning / 98f;
			float into = count - (level - 1) * perLevel;
			return Math.max(0f, Math.min(1f, into / perLevel));
		}
		return XpTable.progressThroughLevel(xp);
	}

	/**
	 * The running count as a sentence, e.g. "You have spun the camera 10 times." Used by both the
	 * unlock popup and the sidebar tooltip, so the two can never disagree.
	 */
	public String resultText(int count)
	{
		if (count <= 0)
		{
			return neverText;
		}
		return "You have " + resultVerb + " " + String.format("%,d", count) + " "
			+ plural(resultUnit, count) + ".";
	}

	/**
	 * Pluralises the head noun of the unit. The head is the last word unless a {@code *} marks an
	 * earlier one, which is what stops "point of damage" becoming "point of damages".
	 */
	private static String plural(String unit, int count)
	{
		int marker = unit.indexOf('*');
		String plain = marker < 0 ? unit : unit.substring(0, marker) + unit.substring(marker + 1);
		if (count == 1)
		{
			return plain;
		}

		int end = marker < 0 ? plain.length() : marker;
		int start = plain.lastIndexOf(' ', end - 1) + 1;
		return plain.substring(0, start) + suffix(plain.substring(start, end)) + plain.substring(end);
	}

	/** Nouns that are already their own plural. "512 damages" and "40 fishes" both read badly. */
	private static final Set<String> UNCOUNTABLE = ImmutableSet.of("damage", "ore", "fish");

	/** Enough of English to handle "kiss" becoming "kisses" rather than "kisss". */
	private static String suffix(String word)
	{
		if (UNCOUNTABLE.contains(word))
		{
			return word;
		}
		if (word.endsWith("s") || word.endsWith("x") || word.endsWith("ch") || word.endsWith("sh"))
		{
			return word + "es";
		}
		return word + "s";
	}
}

package com.tommyknight.unachievements;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(UnachievementsPlugin.CONFIG_GROUP)
public interface UnachievementsConfig extends Config
{
	@ConfigItem(
		keyName = "showPopup",
		name = "Show popup",
		description = "Display the on screen banner when you unlock something",
		position = 1
	)
	default boolean showPopup()
	{
		return true;
	}

	@Range(min = 2, max = 15)
	@ConfigItem(
		keyName = "popupSeconds",
		name = "Popup duration",
		description = "How many seconds the banner stays on screen",
		position = 2
	)
	default int popupSeconds()
	{
		return 3;
	}

	@ConfigItem(
		keyName = "showChatMessage",
		name = "Chat message",
		description = "Announce unlocks in the chatbox",
		position = 3
	)
	default boolean showChatMessage()
	{
		return true;
	}

	@ConfigItem(
		keyName = "chatColour",
		name = "Chat colour",
		description = "Colour of the plugin's own chatbox messages",
		position = 4
	)
	default Color chatColour()
	{
		// Black, matching the game's own messages and the default chatbox it sits on. Players
		// running a transparent chatbox have scenery behind the text instead, which is the
		// reason this is a setting rather than a constant.
		return Color.BLACK;
	}

	@ConfigItem(
		keyName = "chatFrequency",
		name = "Chat on",
		description = "Whether the chatbox reports every rank a task reaches, or every level",
		position = 5
	)
	default ChatFrequency chatFrequency()
	{
		return ChatFrequency.RANK;
	}

	@ConfigItem(
		keyName = "examineMark",
		name = "Mark unexamined",
		description = "Flag things you have never examined in the right click menu",
		position = 7
	)
	default ExamineMark examineMark()
	{
		// An asterisk on the option. Quiet enough not to feel like the plugin has taken over
		// the menus, and it survives every chatbox and interface style.
		return ExamineMark.ASTERISK;
	}

	@ConfigItem(
		keyName = "examineMarkColour",
		name = "Mark colour",
		description = "Colour used when the mark above is set to Colour",
		position = 8
	)
	default Color examineMarkColour()
	{
		return new Color(0x4FE870);
	}

	@ConfigItem(
		keyName = "playSound",
		name = "Play sound",
		description = "Play a sound effect on unlock",
		position = 6
	)
	default boolean playSound()
	{
		return true;
	}
}

package com.tommyknight.unachievements;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Reproduction of the game's own notification toast, the one used for collection log unlocks and
 * combat tasks.
 *
 * <p>Every number here was read out of the cache rather than eyeballed. The interface is group
 * 660 (NotificationDisplay) and the open and close animations are clientscripts 3346, 3347 and
 * 3348. Reproducing it in an overlay rather than driving the real interface keeps the plugin out
 * of the game's UI state, so a genuine collection log popup arriving mid-unlock cannot collide
 * with ours, and a future change to those scripts cannot break us.
 *
 * <p>From the cache:
 * <ul>
 *   <li>container 178x100, horizontally centred</li>
 *   <li>background is sprite {@link SpriteID#TRADEBACKING_DARK}, stretched to fill</li>
 *   <li>title font 496 (bold 12), main font 494 (plain 11), both shadowed and centred</li>
 *   <li>text colour 0xFF981F, main text line height 12</li>
 *   <li>open grows width by 4 per client tick, then height by 4; close reverses it</li>
 *   <li>height rests at 2 rather than 0, which is why the sliver stays visible</li>
 * </ul>
 *
 * <p>Two deliberate departures from the original: a bevelled edge, because the real box has none
 * and reads as a flat rectangle floating on the scene, and a white flavour line, because ours
 * carries more text than "New item:" ever needs to.
 */
public class UnlockOverlay extends Overlay
{
	private static final int BOX_WIDTH = 178;

	// Six taller than the game's own 100, spent entirely on the heading band so the helm and
	// dagger have a margin instead of touching the top edge. The body keeps its original room.
	private static final int BOX_HEIGHT = 106;
	private static final int MIN_HEIGHT = 2;

	/** Pixels per client tick in the open and close animations. */
	private static final int GROW_STEP = 4;
	private static final int CLIENT_TICK_MS = 20;

	// Window cropped out of the middle of the 190x261 texture sprite. Sized to the box's aspect
	// with a margin either side, because the sprite darkens sharply towards its own edges.
	private static final int SOURCE_WIDTH = 166;
	private static final int SOURCE_HEIGHT = 99;

	/** Base tone under the texture, matching the game's own notification brown. */
	private static final Color BASE_FILL = new Color(0x3A3227);

	/** How much of the texture sprite shows through. Low: it is grain, not a surface. */
	private static final float TEXTURE_ALPHA = 0.28f;

	private static final int HEADING_HEIGHT = 36;

	/** Gap between the icons and the box edge, on the top and the sides alike. */
	private static final int ICON_INSET = 4;

	/**
	 * Item sprites are 36x32. Kept near native size and drawn with interpolation on: at the 23px
	 * they were first drawn at, the nearest neighbour downscale chewed the helm to pieces.
	 */
	private static final int ICON_WIDTH = 31;
	private static final int ICON_HEIGHT = 28;
	/** Clear space in the heading band, between the two tier icons, with a pixel of breathing room. */
	private static final int HEADING_TEXT_WIDTH = BOX_WIDTH - 2 * (ICON_INSET + ICON_WIDTH) - 4;

	private static final int BODY_TOP = HEADING_HEIGHT + 4;
	private static final int BODY_BOTTOM = BOX_HEIGHT - 6;
	private static final int SIDE_INSET = 8;
	private static final int LINE_HEIGHT = 12;

	/** Breathing room between the orange name and the white line under it. */
	private static final int BLOCK_GAP = 5;

	private static final Color TEXT_COLOR = new Color(0xFF981F);
	private static final Color FLAVOUR_COLOR = new Color(0xE4E0D8);
	private static final Color SHADOW = Color.BLACK;

	// The game's own popup has no border at all, which leaves a flat brown rectangle floating on
	// the scene. These three are lifted from SpriteID.BROWN_BORDER (2247), the frame Jagex uses on
	// bordered panels: light on the top and left, dark on the bottom and right, giving a raised
	// edge. The outer line is darker again so the box still reads against a bright sky.
	private static final Color BEVEL_LIGHT = new Color(0x60584B);
	private static final Color BEVEL_DARK = new Color(0x3B342C);
	private static final Color OUTLINE = new Color(0x241F18);

	private static final long WIDTH_MS = (BOX_WIDTH / GROW_STEP) * (long) CLIENT_TICK_MS;
	private static final long HEIGHT_MS = ((BOX_HEIGHT - MIN_HEIGHT) / GROW_STEP) * (long) CLIENT_TICK_MS;

	private final UnachievementsPlugin plugin;
	private final SpriteManager spriteManager;
	private final ItemManager itemManager;
	private final Deque<Unlock> queue = new ArrayDeque<>();
	private final Map<Integer, AsyncBufferedImage> helms = new HashMap<>();
	private final Map<Integer, AsyncBufferedImage> daggers = new HashMap<>();

	private BufferedImage background;
	private Unlock current;
	private long shownAt;

	@Inject
	private UnlockOverlay(UnachievementsPlugin plugin, SpriteManager spriteManager,
		ItemManager itemManager)
	{
		this.plugin = plugin;
		this.spriteManager = spriteManager;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	public void loadSprite()
	{
		spriteManager.getSpriteAsync(SpriteID.SIDE_BACKGROUND, 0, img -> background = img);
	}

	public void enqueue(Unlock unlock)
	{
		queue.add(unlock);
	}

	public void clear()
	{
		queue.clear();
		current = null;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		long holdMs = plugin.getConfig().popupSeconds() * 1000L;
		long totalMs = WIDTH_MS + HEIGHT_MS + holdMs + HEIGHT_MS + WIDTH_MS;
		long now = System.currentTimeMillis();

		if (current != null && now - shownAt > totalMs)
		{
			current = null;
		}
		if (current == null)
		{
			current = queue.poll();
			if (current == null)
			{
				return null;
			}
			shownAt = now;
		}

		if (background == null)
		{
			// Sprite has not come back from the cache yet. Skip this frame rather than draw a
			// half finished box; the request itself is what triggers the load.
			return null;
		}

		long elapsed = now - shownAt;
		int width;
		int height;

		if (elapsed < WIDTH_MS)
		{
			width = (int) (BOX_WIDTH * elapsed / WIDTH_MS);
			height = MIN_HEIGHT;
		}
		else if (elapsed < WIDTH_MS + HEIGHT_MS)
		{
			width = BOX_WIDTH;
			height = MIN_HEIGHT + (int) ((BOX_HEIGHT - MIN_HEIGHT) * (elapsed - WIDTH_MS) / HEIGHT_MS);
		}
		else if (elapsed < WIDTH_MS + HEIGHT_MS + holdMs)
		{
			width = BOX_WIDTH;
			height = BOX_HEIGHT;
		}
		else if (elapsed < WIDTH_MS + HEIGHT_MS + holdMs + HEIGHT_MS)
		{
			long into = elapsed - WIDTH_MS - HEIGHT_MS - holdMs;
			width = BOX_WIDTH;
			height = BOX_HEIGHT - (int) ((BOX_HEIGHT - MIN_HEIGHT) * into / HEIGHT_MS);
		}
		else
		{
			long into = elapsed - WIDTH_MS - HEIGHT_MS - holdMs - HEIGHT_MS;
			width = BOX_WIDTH - (int) (BOX_WIDTH * into / WIDTH_MS);
			height = MIN_HEIGHT;
		}

		if (width <= 0)
		{
			return null;
		}

		// The game keeps the box centred in its 100px slot while the height animates.
		int x = (BOX_WIDTH - width) / 2;
		int y = (BOX_HEIGHT - height) / 2;

		drawTexturedBackground(g, x, y, width, height);
		drawBevel(g, x, y, width, height);

		if (height >= BOX_HEIGHT)
		{
			drawContents(g);
		}

		return new Dimension(BOX_WIDTH, BOX_HEIGHT);
	}

	/**
	 * Draws the mottled panel texture rather than a flat fill.
	 *
	 * <p>{@link SpriteID#SIDE_BACKGROUND} is 190x261 and vignettes heavily at its own edges, so a
	 * centred window is cropped out of the middle instead of stretching the whole sprite. The
	 * window scales with the box, which keeps the texture at a constant size on screen and makes
	 * the open animation read as a reveal rather than a squash.
	 */
	private void drawTexturedBackground(Graphics2D g, int x, int y, int width, int height)
	{
		// Flat base first, then the texture at low opacity over it. The sprite on its own is
		// lighter than the game's notification brown and the grain reads far too strongly at this
		// size; laying it over the base keeps the tone exact and leaves only a hint of mottling.
		g.setColor(BASE_FILL);
		g.fillRect(x, y, width, height);

		int cx = background.getWidth() / 2;
		int cy = background.getHeight() / 2;

		int srcW = Math.max(1, SOURCE_WIDTH * width / BOX_WIDTH);
		int srcH = Math.max(1, SOURCE_HEIGHT * height / BOX_HEIGHT);

		Composite previous = g.getComposite();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, TEXTURE_ALPHA));
		g.drawImage(background,
			x, y, x + width, y + height,
			cx - srcW / 2, cy - srcH / 2, cx + srcW / 2, cy + srcH / 2,
			null);
		g.setComposite(previous);
	}

	/** Raised panel edge: outer outline, then light top and left over dark bottom and right. */
	private static void drawBevel(Graphics2D g, int x, int y, int width, int height)
	{
		int right = x + width - 1;
		int bottom = y + height - 1;

		g.setColor(OUTLINE);
		g.drawRect(x, y, width - 1, height - 1);

		if (width < 4 || height < 4)
		{
			// Mid animation the box is a sliver; an inner bevel would just muddy it.
			return;
		}

		g.setColor(BEVEL_LIGHT);
		g.drawLine(x + 1, y + 1, right - 1, y + 1);
		g.drawLine(x + 1, y + 1, x + 1, bottom - 1);

		g.setColor(BEVEL_DARK);
		g.drawLine(x + 1, bottom - 1, right - 1, bottom - 1);
		g.drawLine(right - 1, y + 1, right - 1, bottom - 1);
	}

	private void drawContents(Graphics2D g)
	{
		int textWidth = BOX_WIDTH - SIDE_INSET * 2;

		// Heading band: bold orange, closed off underneath by a black rule running the full width
		// of the box, exactly like the collection log toast. The heading stays orange whatever
		// the tier; the helm and dagger carry the tier instead, because several of the tier
		// colours are unreadable as text.
		String heading = current.getHeading();
		g.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics headingMetrics = g.getFontMetrics();

		// The helm and dagger own the ends of the band, and the heading is drawn under them, so
		// one too wide is not clipped, it is sat on. Anything that does not fit the gap between
		// the icons drops to the small font rather than colliding.
		if (headingMetrics.stringWidth(heading) > HEADING_TEXT_WIDTH)
		{
			g.setFont(FontManager.getRunescapeSmallFont());
			headingMetrics = g.getFontMetrics();
		}

		int headingX = SIDE_INSET + (textWidth - headingMetrics.stringWidth(heading)) / 2;
		int headingY = (HEADING_HEIGHT + headingMetrics.getAscent()) / 2 - 2;

		drawShadowed(g, heading, headingX, headingY, TEXT_COLOR);
		drawTierIcons(g);

		g.setColor(SHADOW);
		g.fillRect(2, HEADING_HEIGHT, BOX_WIDTH - 4, 2);

		// Body: the specific thing in orange, then the flavour in white, then the award.
		g.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics bodyMetrics = g.getFontMetrics();

		List<Line> lines = new ArrayList<>();
		for (String line : wrap(bodyMetrics, current.getDetail(), textWidth))
		{
			lines.add(new Line(line, TEXT_COLOR, 0));
		}

		// The first white line is pushed down a little. At a flat line height the orange block and
		// the white one read as one paragraph that changes colour halfway through, rather than as
		// a name with a note under it. No gap when there is nothing above it to separate from.
		boolean firstFlavour = !lines.isEmpty();
		for (String line : wrap(bodyMetrics, current.getFlavour(), textWidth))
		{
			lines.add(new Line(line, FLAVOUR_COLOR, firstFlavour ? BLOCK_GAP : 0));
			firstFlavour = false;
		}

		int available = BODY_BOTTOM - BODY_TOP;

		// Drop trailing lines rather than let them spill past the bottom edge. Measured rather
		// than counted, since the gap makes lines no longer a fixed height each.
		int blockHeight = height(lines);
		while (lines.size() > 1 && blockHeight > available)
		{
			lines.remove(lines.size() - 1);
			blockHeight = height(lines);
		}

		int lineY = BODY_TOP + Math.max(0, (available - blockHeight) / 2) + bodyMetrics.getAscent();

		Rectangle oldClip = g.getClipBounds() == null ? null : g.getClipBounds().getBounds();
		g.setClip(0, BODY_TOP, BOX_WIDTH, available);

		for (Line line : lines)
		{
			lineY += line.gap;
			int lineX = SIDE_INSET + (textWidth - bodyMetrics.stringWidth(line.text)) / 2;
			drawShadowed(g, line.text, lineX, lineY, line.color);
			lineY += LINE_HEIGHT;
		}

		g.setClip(oldClip);
	}

	/**
	 * Helm on the left of the heading, dagger on the right, both of the tier just reached. They
	 * mirror the sidebar header and make the reward read as an object rather than a word.
	 */
	private void drawTierIcons(Graphics2D g)
	{
		Tier tier = current.getTier();

		// Drawing one before it has loaded is a no op, so no readiness check is needed.
		Object previous = g.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			RenderingHints.VALUE_INTERPOLATION_BILINEAR);

		int y = ICON_INSET;
		g.drawImage(helms.computeIfAbsent(tier.getHelmItemId(), itemManager::getImage),
			ICON_INSET, y, ICON_WIDTH, ICON_HEIGHT, null);
		g.drawImage(daggers.computeIfAbsent(tier.getDaggerItemId(), itemManager::getImage),
			BOX_WIDTH - ICON_INSET - ICON_WIDTH, y, ICON_WIDTH, ICON_HEIGHT, null);

		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			previous == null ? RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR : previous);
	}

	/** The game draws all interface text with a one pixel black drop shadow. */
	private static void drawShadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(SHADOW);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	private static List<String> wrap(FontMetrics fm, String text, int maxWidth)
	{
		List<String> lines = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		for (String word : text.split(" "))
		{
			String candidate = line.length() == 0 ? word : line + " " + word;
			if (fm.stringWidth(candidate) > maxWidth && line.length() > 0)
			{
				lines.add(line.toString());
				line.setLength(0);
				line.append(word);
			}
			else
			{
				line.setLength(0);
				line.append(candidate);
			}
		}
		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		return lines;
	}

	private static int height(List<Line> lines)
	{
		int total = 0;
		for (Line line : lines)
		{
			total += line.gap + LINE_HEIGHT;
		}
		return total;
	}

	private static class Line
	{
		private final String text;
		private final Color color;

		/** Extra pixels above this line, used to hold the two colour blocks apart. */
		private final int gap;

		private Line(String text, Color color, int gap)
		{
			this.text = text;
			this.color = color;
			this.gap = gap;
		}
	}
}

package com.tommyknight.unachievements;

import java.awt.Color;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

/**
 * How the right click menu flags something that has never been examined.
 *
 * <p>The mark goes on the option, the word "Examine", rather than on the thing's name. Item names
 * in menus are already coloured by type, and a mark layered over that either loses the colour or
 * fights it, where the option is plain and has room to carry a signal.
 *
 * <p>The collection tasks match the option exactly, so anything added here has to come back off
 * before the click is translated. Colour and underline are free, since tags are stripped on the
 * way through anyway; the plain text marks are removed by {@link #strip}, which is called at the
 * single point where a clicked option is normalised.
 *
 * <p>There is no bold and no italic. The game's fonts are bitmaps with no such variants, which is
 * why nothing in RuneLite emits either.
 */
public enum ExamineMark
{
	OFF("Off", null),
	COLOUR("Colour", null),
	QUESTION("Question mark", "?"),
	ASTERISK("Asterisk", " *");

	private final String displayName;

	/** Text appended to the option, or null when the mark is carried by a tag instead. */
	private final String suffix;

	ExamineMark(String displayName, String suffix)
	{
		this.displayName = displayName;
		this.suffix = suffix;
	}

	/** Decorates the menu option of something not yet examined. */
	String apply(String option, Color colour)
	{
		switch (this)
		{
			case COLOUR:
				return ColorUtil.wrapWithColorTag(Text.removeTags(option), colour);
			case OFF:
				return option;
			default:
				return option + suffix;
		}
	}

	/**
	 * Removes any mark this class may have added, so a decorated option matches the filters again.
	 *
	 * <p>Every suffix is tried rather than only the active one. A player who switches setting mid
	 * session would otherwise have the menu still showing the old mark on entries built before the
	 * change, and that click would go uncounted.
	 */
	static String strip(String option)
	{
		for (ExamineMark mark : values())
		{
			if (mark.suffix != null && option.endsWith(mark.suffix))
			{
				return option.substring(0, option.length() - mark.suffix.length());
			}
		}
		return option;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.tommyknight.unachievements;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.function.IntSupplier;
import lombok.Getter;
import lombok.Setter;

/**
 * Holds every task's progress and turns incoming {@link TaskEvent}s into levels, tiers and
 * unlocks.
 *
 * <p>Overall rank is the tier of the player's <em>mean</em> task level, so it self scales as
 * tasks are added to the registry rather than needing its own threshold table.
 */
public class ProgressTracker
{
	/**
	 * Every task's stored state, one entry per registry task, populated once in the constructor.
	 *
	 * <p><b>Never structurally modify this map.</b> It is read from the Swing thread while the
	 * client thread is writing through it: the panel walks every task on refresh, and events land
	 * on the client thread. Concurrent {@code computeIfAbsent} on a plain HashMap can corrupt the
	 * bucket array, so entries are created up front and only their contents ever change. That is
	 * also why {@link #reset()} overwrites values rather than clearing.
	 */
	private final Map<String, TaskProgress> progress = new HashMap<>();

	@Getter
	private final StatTracker stats = new StatTracker();

	private final Map<TaskEventType, List<Task>> byTrigger = new EnumMap<>(TaskEventType.class);

	/**
	 * Task ids the player has silenced. Notification only: a muted task still counts, still levels
	 * and still pulls its weight in the overall rank, it just stops announcing itself.
	 *
	 * <p>Deliberately outside {@link #reset()}. That runs on every login and on Reset Progress, and
	 * a mute is a preference rather than progress, so wiping it there would unmute everything each
	 * time the player switched account.
	 */
	private final Set<String> muted = new HashSet<>();

	/** Current game tick, for the one per tick cap. Zero until the plugin wires the client in. */
	private IntSupplier clock = () -> 0;

	private Consumer<Unlock> unlockListener;

	/**
	 * Told about every level that is not also a tier up. Separate from the unlock listener because
	 * a level is chatbox news at most: a popup for each one would cover the screen.
	 */
	private BiConsumer<Task, Integer> levelListener;

	private Runnable changeListener;

	/** Last rank announced, so a rank up fires once rather than on every subsequent action. */
	private Tier announcedRank;

	/**
	 * When the numbers on the Stats tab started counting: first sight of this account, or the last
	 * Reset Progress. Epoch milliseconds, zero when nothing is loaded.
	 */
	@Getter
	@Setter
	private long trackingSince;

	public ProgressTracker()
	{
		for (TaskEventType type : TaskEventType.values())
		{
			byTrigger.put(type, new ArrayList<>());
		}
		for (Task task : TaskRegistry.TASKS)
		{
			byTrigger.get(task.getTrigger()).add(task);
			progress.put(task.getId(), new TaskProgress());
		}
	}

	public void setClock(IntSupplier clock)
	{
		this.clock = clock;
	}

	public void setListeners(Consumer<Unlock> unlockListener,
		BiConsumer<Task, Integer> levelListener, Runnable changeListener)
	{
		this.unlockListener = unlockListener;
		this.levelListener = levelListener;
		this.changeListener = changeListener;
	}

	public void handle(TaskEvent event)
	{
		// Stats ride the same stream. They never unlock anything, so their movement only decides
		// whether the panel is worth redrawing.
		boolean changed = stats.handle(event);

		List<Task> candidates = byTrigger.get(event.getType());
		if (candidates.isEmpty())
		{
			if (changed && changeListener != null)
			{
				changeListener.run();
			}
			return;
		}

		for (Task task : candidates)
		{
			if (!task.matches(event))
			{
				continue;
			}

			TaskProgress state = state(task);

			// One count per tick for anything a mouse can repeat. Without it, Can't Reach and the
			// other chat driven tasks level at whatever rate the player can click, which is a
			// measure of their mouse rather than of anything they did.
			if (task.isThrottled() && event.getType().isSpammable())
			{
				int tick = clock.getAsInt();
				if (state.getLastTick() == tick)
				{
					continue;
				}
				state.setLastTick(tick);
			}

			int countBefore = state.getCount();
			int levelBefore = task.levelFor(countBefore, state.getXp());
			Tier tierBefore = Tier.effective(levelBefore, countBefore, guarded(task));

			int units = 1;

			if (task.isUnique())
			{
				if (!state.addUnique(event.getValue()))
				{
					// Already collected. Not a failure, just nothing to record.
					continue;
				}
			}
			else
			{
				units = task.incrementFor(event);
				if (units <= 0)
				{
					// A weighted task measures the value, so an event carrying none is not an
					// action at all. Paying experience for it anyway let Damage Taken level off
					// blocked hits while its count, measured in damage, stayed put.
					continue;
				}
				state.setCount(countBefore + units);
			}

			// Experience is earned at the rate of the tier the task was already sitting at, so a
			// single action can never pay itself the bonus of the tier it just unlocked. Weighted
			// tasks pay per unit, keeping the level on the same scale as the count.
			state.setXp(state.getXp() + (long) task.xpFor(tierBefore) * units);
			state.setLastUpdated(System.currentTimeMillis());

			changed = true;

			int countAfter = state.getCount();
			int levelAfter = task.levelFor(countAfter, state.getXp());
			Tier tierAfter = Tier.effective(levelAfter, countAfter, guarded(task));

			// Muting is checked here rather than at the presentation end, so one test covers the
			// popup, the chat line and the sound at once.
			//
			// A tier up reports as a tier up and nothing else. It is also a level up, but saying
			// both would put two lines in the chatbox for one event, and the tier line is the one
			// carrying the news.
			if (!isMuted(task))
			{
				if (tierAfter != tierBefore)
				{
					fire(new Unlock(tierAfter.getDisplayName() + " Rank",
						task.getName(), task.resultText(countAfter), tierAfter));
				}
				else if (levelAfter > levelBefore && levelListener != null)
				{
					levelListener.accept(task, levelAfter);
				}
			}
		}

		if (!changed)
		{
			return;
		}

		checkRankUp();

		if (changeListener != null)
		{
			changeListener.run();
		}
	}

	private void checkRankUp()
	{
		Tier rank = getRank();
		if (announcedRank == null)
		{
			announcedRank = rank;
			return;
		}
		if (rank != announcedRank)
		{
			announcedRank = rank;
			// Reads "to" rather than "from" because the chat line is now just this sentence, and
			// the rank left behind is the half nobody cares about.
			// Shouted, and named in full. A task tier up is headed "<Tier> Rank", so a plain
			// "Rank Up" next to it read as the same event misfiring rather than the much rarer
			// thing it is.
			fire(new Unlock("OVERALL RANK UP", rank.getDisplayName(),
				"Promoted to " + rank.getDisplayName() + ".", rank));
		}
	}

	public boolean isMuted(Task task)
	{
		return muted.contains(task.getId());
	}

	/** @return the new state, so a caller toggling one does not have to ask again */
	boolean toggleMuted(Task task)
	{
		if (!muted.remove(task.getId()))
		{
			muted.add(task.getId());
			return true;
		}
		return false;
	}

	Set<String> getMuted()
	{
		return muted;
	}

	void setMuted(Set<String> ids)
	{
		muted.clear();
		muted.addAll(ids);
	}

	private void fire(Unlock unlock)
	{
		if (unlockListener != null)
		{
			unlockListener.accept(unlock);
		}
	}

	/** Only experience based tasks need the action floor; linear tasks pace themselves. */
	private static boolean guarded(Task task)
	{
		return task.getMode() == Task.Mode.XP;
	}

	/** Never null: the constructor seeded an entry for every task the registry holds. */
	TaskProgress state(Task task)
	{
		return progress.get(task.getId());
	}

	public int getCount(Task task)
	{
		return state(task).getCount();
	}

	public long getXp(Task task)
	{
		return state(task).getXp();
	}

	/**
	 * Whether a collection task has already recorded this value.
	 *
	 * <p>False for anything that is not a collection, since a plain counter keeps no record
	 * of what it counted.
	 */
	public boolean hasSeen(Task task, int value)
	{
		if (task == null || value < 0)
		{
			return false;
		}
		java.util.BitSet seen = state(task).getSeen();
		return seen != null && seen.get(value);
	}

	public long getLastUpdated(Task task)
	{
		return state(task).getLastUpdated();
	}

	public int getLevel(Task task)
	{
		TaskProgress s = state(task);
		return task.levelFor(s.getCount(), s.getXp());
	}

	public Tier getTier(Task task)
	{
		TaskProgress s = state(task);
		return Tier.effective(task.levelFor(s.getCount(), s.getXp()), s.getCount(), guarded(task));
	}

	public float getProgress(Task task)
	{
		TaskProgress s = state(task);
		return task.progressFor(s.getCount(), s.getXp());
	}

	/** Sum of every task's level. A fresh account starts at one per task, never zero. */
	public int getTotalLevel()
	{
		int total = 0;
		for (Task task : TaskRegistry.TASKS)
		{
			total += getLevel(task);
		}
		return total;
	}

	/**
	 * Every counted action across every task. Shown in the header instead of total experience
	 * because it moves in ones: a player watching it tick up can see their own clicks land, where
	 * an xp total jumps by whatever the current tier multiplier happens to be.
	 */
	public long getTotalActions()
	{
		long total = 0;
		for (Task task : TaskRegistry.TASKS)
		{
			total += getCount(task);
		}
		return total;
	}

	/** Mean task level, which the overall rank tier bands off. */
	public float getMeanLevel()
	{
		int tasks = TaskRegistry.TASKS.size();
		return tasks == 0 ? 1f : getTotalLevel() / (float) tasks;
	}

	public Tier getRank()
	{
		return Tier.forLevel((int) getMeanLevel());
	}

	/** Highest tier held by any single task. Drives the dagger in the header. */
	public Tier getBestTier()
	{
		Tier best = Tier.BRONZE;
		for (Task task : TaskRegistry.TASKS)
		{
			Tier tier = getTier(task);
			if (tier.ordinal() > best.ordinal())
			{
				best = tier;
			}
		}
		return best;
	}

	Map<String, TaskProgress> getProgress()
	{
		return progress;
	}

	/** Value behind one stat line, whether it keeps its own counter or reads a task. */
	public long statValue(Stat stat)
	{
		if (stat.isOwnCounter())
		{
			return stats.get(stat.getCounterId());
		}

		long total = 0;
		for (String id : stat.getTaskIds())
		{
			Task task = TaskRegistry.byId(id);
			if (task != null)
			{
				total += getCount(task);
			}
		}
		return total;
	}

	public void reset()
	{
		stats.reset();
		// Overwritten rather than cleared. Clearing is a structural change, and the panel may be
		// reading this map on the Swing thread at the same moment.
		for (String id : progress.keySet())
		{
			progress.put(id, new TaskProgress());
		}
		announcedRank = null;
		// Not carried over. A stale date from the previous account is worse than showing none.
		trackingSince = 0;
	}

	/** Called after a load so the first action does not announce a rank up from Bronze. */
	void syncAnnouncedRank()
	{
		announcedRank = getRank();
	}
}

package com.tommyknight.unachievements;

import com.google.common.collect.ImmutableSet;
import java.util.Set;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;

/**
 * Reference data for the handful of tasks that care about a specific thing rather than a specific
 * action. Kept together rather than inline in the registry, which would otherwise stop being
 * readable as a table.
 *
 * <p>These lists are the common overworld variants only. Missing an obscure id means a task
 * undercounts slightly, which is a far better failure than matching something unintended.
 */
final class TaskIds
{
	static final Set<Integer> CHICKENS = ImmutableSet.of(
		NpcID.CHICKEN,
		NpcID.CHICKEN_BROWN
	);

	static final int CABBAGE = ItemID.CABBAGE;
	static final int BEER = ItemID.BEER;

	private TaskIds()
	{
	}
}

package com.tommyknight.unachievements;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Running totals behind the Stats tab.
 *
 * <p>Only stats with their own counter live here. The rest read a task's count straight off
 * {@link ProgressTracker}, so there is nothing to keep in step and nothing extra to store.
 */
class StatTracker
{
	/**
	 * <b>Never structurally modify this map.</b> Same reasoning as
	 * {@link ProgressTracker#state(Task)}: the Swing thread reads it while the client thread
	 * writes, so every key is created up front and only values ever change afterwards.
	 */
	private final Map<String, Long> counters = new HashMap<>();

	private final Map<TaskEventType, List<Stat>> byTrigger = new EnumMap<>(TaskEventType.class);

	StatTracker()
	{
		for (TaskEventType type : TaskEventType.values())
		{
			byTrigger.put(type, new ArrayList<>());
		}
		for (Stat stat : StatRegistry.STATS)
		{
			if (stat.isOwnCounter())
			{
				byTrigger.get(stat.getTrigger()).add(stat);
				counters.put(stat.getCounterId(), 0L);
			}
		}
	}

	/** @return true if anything moved, so the panel knows whether it is worth redrawing */
	boolean handle(TaskEvent event)
	{
		boolean changed = false;
		for (Stat stat : byTrigger.get(event.getType()))
		{
			if (!stat.matches(event))
			{
				continue;
			}
			int increment = stat.incrementFor(event);
			if (increment <= 0)
			{
				continue;
			}
			counters.merge(stat.getCounterId(), (long) increment, Long::sum);
			changed = true;
		}
		return changed;
	}

	long get(String counterId)
	{
		return counters.getOrDefault(counterId, 0L);
	}

	Map<String, Long> getCounters()
	{
		return counters;
	}

	/**
	 * Applies a loaded save. Keys the registry no longer declares are dropped rather than kept,
	 * which is the right answer for a stat that has since been removed, and keeps this from
	 * inserting new keys into a map two threads are using.
	 */
	void setCounters(Map<String, Long> loaded)
	{
		for (Map.Entry<String, Long> entry : counters.entrySet())
		{
			Long value = loaded.get(entry.getKey());
			entry.setValue(value == null ? 0L : value);
		}
	}

	void reset()
	{
		for (Map.Entry<String, Long> entry : counters.entrySet())
		{
			entry.setValue(0L);
		}
	}
}

package com.tommyknight.unachievements;

import java.awt.BasicStroke;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import net.runelite.client.ui.FontManager;

/**
 * One task in the sidebar list.
 *
 * <p>The level is the prominent figure rather than the tier. Past level 60 every task is Dragon
 * forever, so the tier stops carrying information and the number has to take over; the tier keeps
 * the row's background colour and its label.
 */
class TaskRow extends JPanel
{
	private static final int BAR_HEIGHT = 3;
	private static final Color LOCKED_BG = new Color(26, 26, 26);
	private static final Color LOCKED_TEXT = new Color(120, 118, 114);
	private static final Color DESC_TEXT = new Color(150, 147, 142);

	/** Light enough to read against the locked grey and every tier background alike. */
	private static final Color MUTE_MARK = new Color(0xC8C4BC);

	/** Wrap width for the description. The sidebar is 225px before borders and scrollbar. */
	private static final int DESC_WIDTH = 185;

	/**
	 * Shown beside the name of a silenced task. A speaker or a bell is unreadable mush at this
	 * size, where the circle and slash of a "no" sign is legible down to about six pixels.
	 */
	private static final Image MUTE_ICON = buildMuteIcon();

	private final Task task;
	private final JLabel nameLabel = new JLabel();
	private final JLabel descLabel = new JLabel();
	private final JLabel levelLabel = new JLabel();
	private final JLabel tierLabel = new JLabel();
	private final JLabel muteLabel = new JLabel(new ImageIcon(MUTE_ICON));
	private final JMenuItem muteItem = new JMenuItem();

	private float progress;

	TaskRow(Task task, Consumer<Task> onToggleMute)
	{
		this.task = task;

		setLayout(new BorderLayout(0, 3));
		// Bottom inset leaves room for the progress bar drawn in paintComponent.
		setBorder(BorderFactory.createEmptyBorder(7, 8, 7 + BAR_HEIGHT, 8));

		nameLabel.setFont(FontManager.getRunescapeSmallFont());
		nameLabel.setForeground(Color.WHITE);
		nameLabel.setText(task.getName());

		levelLabel.setFont(FontManager.getRunescapeBoldFont());
		levelLabel.setForeground(Color.WHITE);

		muteLabel.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 4));
		muteLabel.setVisible(false);

		JPanel top = new JPanel(new BorderLayout(6, 0));
		top.setOpaque(false);
		top.add(muteLabel, BorderLayout.WEST);
		top.add(nameLabel, BorderLayout.CENTER);
		top.add(levelLabel, BorderLayout.EAST);

		descLabel.setFont(FontManager.getRunescapeSmallFont());
		descLabel.setForeground(DESC_TEXT);
		descLabel.setText(wrapped(task.getDescription()));

		tierLabel.setFont(FontManager.getRunescapeSmallFont());
		tierLabel.setForeground(LOCKED_TEXT);
		tierLabel.setAlignmentX(Component.RIGHT_ALIGNMENT);

		JPanel bottom = new JPanel();
		bottom.setLayout(new BoxLayout(bottom, BoxLayout.X_AXIS));
		bottom.setOpaque(false);
		Component glue = Box.createHorizontalGlue();
		bottom.add(glue);
		bottom.add(tierLabel);

		add(top, BorderLayout.NORTH);
		add(descLabel, BorderLayout.CENTER);
		add(bottom, BorderLayout.SOUTH);

		muteItem.addActionListener(e -> onToggleMute.accept(task));
		JPopupMenu popup = new JPopupMenu();
		popup.add(muteItem);
		setComponentPopupMenu(popup);

		// Swing does not bubble mouse events, so a listener here would never see a click that
		// landed on a label. setInheritsPopupMenu is the built in way round it: a child with no
		// popup of its own walks up to its parent for one. It has to be set on every link in the
		// chain, which is why the inner panels are listed as well as the labels.
		inheritPopup(top, bottom, nameLabel, descLabel, levelLabel, tierLabel, muteLabel, glue);
	}

	private static void inheritPopup(Component... components)
	{
		for (Component component : components)
		{
			if (component instanceof JComponent)
			{
				((JComponent) component).setInheritsPopupMenu(true);
			}
		}
	}

	private static Image buildMuteIcon()
	{
		BufferedImage image = new BufferedImage(9, 9, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(MUTE_MARK);
		g.setStroke(new BasicStroke(1.3f));
		g.drawOval(1, 1, 6, 6);
		g.drawLine(2, 6, 6, 2);
		g.dispose();
		return image;
	}

	/** HTML is the only way to get a JLabel to wrap inside a fixed width column. */
	private static String wrapped(String text)
	{
		return "<html><body style='width:" + DESC_WIDTH + "px'>" + text + "</body></html>";
	}

	void update(ProgressTracker tracker)
	{
		int count = tracker.getCount(task);
		int level = tracker.getLevel(task);
		Tier tier = tracker.getTier(task);

		progress = tracker.getProgress(task);

		setBackground(count == 0 ? LOCKED_BG : tier.getBackground());

		levelLabel.setText("Lv " + level);
		tierLabel.setText(tier.getDisplayName());
		tierLabel.setForeground(count == 0 ? LOCKED_TEXT : tier.getColor());

		boolean muted = tracker.isMuted(task);
		muteLabel.setVisible(muted);
		muteItem.setText(muted ? "Unmute" : "Mute");

		// Count on hover, targets never. Same sentence the popup uses.
		setToolTipText(task.resultText(count));

		repaint();
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);

		int y = getHeight() - BAR_HEIGHT;
		g.setColor(Palette.TROUGH);
		g.fillRect(0, y, getWidth(), BAR_HEIGHT);
		g.setColor(Palette.PROGRESS);
		g.fillRect(0, y, Math.round(getWidth() * progress), BAR_HEIGHT);
	}
}

