package com.tommyknight.unachievements;

import java.util.BitSet;
import lombok.Getter;
import lombok.Setter;

/**
 * Stored state for one task.
 *
 * <p>Experience is stored rather than derived because the rate depends on the tier the task was
 * sitting at when each action happened, which a bare count cannot reconstruct. The upside is that
 * retuning a task later never retroactively rewrites what a player already earned.
 *
 * <p>Unique tasks keep a bitset of the values they have seen and take their count from its
 * cardinality, so the count and the set can never disagree.
 */
@Getter
class TaskProgress
{
	@Setter
	private int count;

	@Setter
	private long xp;

	/**
	 * Game tick this task last counted on, for the one per tick cap. Deliberately not saved: it
	 * only matters across a handful of ticks and means nothing after a reload.
	 */
	@Setter
	private int lastTick = -1;

	/**
	 * Wall clock time this task last counted, in epoch milliseconds. Zero for a task never
	 * touched. Saved, unlike {@link #lastTick}, because the point of it is to still mean something
	 * a week later.
	 */
	@Setter
	private long lastUpdated;

	/** Values already seen. Null for everything except unique tasks. */
	private BitSet seen;

	/**
	 * Records a value against a unique task.
	 *
	 * @return true if this value is new, false if it has been seen before
	 */
	boolean addUnique(int value)
	{
		if (value < 0)
		{
			// BitSet cannot index negatives, and a negative id means the event carried no key.
			return false;
		}
		if (seen == null)
		{
			seen = new BitSet();
		}
		if (seen.get(value))
		{
			return false;
		}
		seen.set(value);
		count = seen.cardinality();
		return true;
	}

	void setSeen(BitSet seen)
	{
		this.seen = seen;
		this.count = seen == null ? 0 : seen.cardinality();
	}
}

