package com.tommyknight.unachievements;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.BitSet;
import java.util.Base64;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Reads and writes task progress, keyed on the account hash so a display name change cannot
 * orphan it.
 *
 * <p>Three keys rather than one object, so the original counts key keeps its shape and existing
 * saves load without a migration. Unique tasks store a bitset rather than a list of ids: a player
 * who examines five thousand items would otherwise carry a thirty kilobyte JSON array, where the
 * bitset is a flat few kilobytes however full it gets.
 */
@Slf4j
public class ProgressStore
{
	private static final Type COUNTS_TYPE = new TypeToken<Map<String, Integer>>()
	{
	}.getType();

	private static final Type XP_TYPE = new TypeToken<Map<String, Long>>()
	{
	}.getType();

	private static final Type UNIQUE_TYPE = new TypeToken<Map<String, String>>()
	{
	}.getType();

	private static final Type STATS_TYPE = new TypeToken<Map<String, Long>>()
	{
	}.getType();

	private static final Type MUTED_TYPE = new TypeToken<Set<String>>()
	{
	}.getType();

	/**
	 * Current shape of saved progress. Bump it and add a branch to {@link #migrate} whenever a
	 * retune leaves old saves on the wrong scale.
	 */
	private static final int SCHEMA_VERSION = 1;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	private static String countsKey(long accountHash)
	{
		return "progress_" + accountHash;
	}

	private static String xpKey(long accountHash)
	{
		return "xp_" + accountHash;
	}

	private static String uniqueKey(long accountHash)
	{
		return "unique_" + accountHash;
	}

	private static String statsKey(long accountHash)
	{
		return "stats_" + accountHash;
	}

	private static String recentKey(long accountHash)
	{
		return "recent_" + accountHash;
	}

	private static String versionKey(long accountHash)
	{
		return "version_" + accountHash;
	}

	private static String sinceKey(long accountHash)
	{
		return "since_" + accountHash;
	}

	/** Not keyed on the account. Silencing a task is a preference, and it travels with the player. */
	private static final String MUTED_KEY = "muted";

	public void load(long accountHash, ProgressTracker tracker)
	{
		tracker.reset();
		if (accountHash == -1)
		{
			return;
		}

		Map<String, Integer> counts = read(countsKey(accountHash), COUNTS_TYPE);
		Map<String, Long> xp = read(xpKey(accountHash), XP_TYPE);
		Map<String, String> unique = read(uniqueKey(accountHash), UNIQUE_TYPE);
		Map<String, Long> recent = read(recentKey(accountHash), XP_TYPE);

		tracker.getStats().setCounters(read(statsKey(accountHash), STATS_TYPE));

		// First sight of an account starts the clock now, written straight away rather than left to
		// the next save: a player who logs in and does nothing would otherwise reset it every time.
		// Saves that predate the key get today's date, which is the honest answer, since nobody
		// recorded when they actually began.
		Long since = configManager.getConfiguration(UnachievementsPlugin.CONFIG_GROUP,
			sinceKey(accountHash), long.class);
		if (since == null)
		{
			since = System.currentTimeMillis();
			writeSince(accountHash, since);
		}
		tracker.setTrackingSince(since);

		for (Task task : TaskRegistry.TASKS)
		{
			TaskProgress state = tracker.state(task);

			if (task.isUnique())
			{
				String encoded = unique.get(task.getId());
				if (encoded != null && !encoded.isEmpty())
				{
					state.setSeen(decode(encoded));
				}
			}
			else
			{
				Integer count = counts.get(task.getId());
				if (count != null)
				{
					state.setCount(count);
				}
			}

			Long touched = recent.get(task.getId());
			if (touched != null)
			{
				state.setLastUpdated(touched);
			}

			Long stored = xp.get(task.getId());
			if (stored != null)
			{
				state.setXp(stored);
			}
			else if (state.getCount() > 0)
			{
				// Saves written before experience existed only have counts. Backfill at the base
				// rate, which treats the whole history as if it happened at Bronze. Slightly
				// undervalues old progress, which beats wiping it.
				state.setXp((long) state.getCount() * task.xpFor(Tier.BRONZE));
			}
		}

		migrate(accountHash, tracker);
		tracker.syncAnnouncedRank();
	}

	/**
	 * One off repairs to saved progress after a task is retuned.
	 *
	 * <p>Experience is banked rather than recomputed from the count, which is what stops a retune
	 * rewriting history. The flip side is that lowering a rate leaves everything already earned on
	 * the old scale, so anything that should follow the new curve has to be rescaled here.
	 *
	 * <p>Versioned per account rather than globally: a second account logging in later has its own
	 * old scale progress and needs the same pass.
	 */
	private void migrate(long accountHash, ProgressTracker tracker)
	{
		int version = readVersion(accountHash);
		if (version >= SCHEMA_VERSION)
		{
			return;
		}

		if (version < 1)
		{
			// Spammer went from 6 base experience per click to 1. Divide what is already banked by
			// the same factor, or the player keeps a level the new rate could never have reached.
			Task spammer = TaskRegistry.byId("clicks");
			if (spammer != null)
			{
				TaskProgress state = tracker.state(spammer);
				state.setXp(state.getXp() / 6);
			}
		}

		// Written before the version, so a crash in between repeats the migration rather than
		// skipping it. Repeating a rescale would be wrong, but losing one entirely is worse.
		save(accountHash, tracker);
		configManager.setConfiguration(UnachievementsPlugin.CONFIG_GROUP, versionKey(accountHash),
			String.valueOf(SCHEMA_VERSION));
	}

	private int readVersion(long accountHash)
	{
		Integer version = configManager.getConfiguration(UnachievementsPlugin.CONFIG_GROUP,
			versionKey(accountHash), int.class);
		return version == null ? 0 : version;
	}

	public Set<String> loadMuted()
	{
		String json = configManager.getConfiguration(UnachievementsPlugin.CONFIG_GROUP, MUTED_KEY);
		if (json == null || json.isEmpty())
		{
			return new HashSet<>();
		}
		try
		{
			Set<String> loaded = gson.fromJson(json, MUTED_TYPE);
			return loaded == null ? new HashSet<>() : loaded;
		}
		catch (Exception e)
		{
			log.warn("Failed to load Unachievements mutes", e);
			return new HashSet<>();
		}
	}

	public void saveMuted(Set<String> muted)
	{
		configManager.setConfiguration(UnachievementsPlugin.CONFIG_GROUP, MUTED_KEY,
			gson.toJson(muted));
	}

	public void save(long accountHash, ProgressTracker tracker)
	{
		if (accountHash == -1)
		{
			return;
		}

		Map<String, Integer> counts = new HashMap<>();
		Map<String, Long> xp = new HashMap<>();
		Map<String, String> unique = new HashMap<>();
		Map<String, Long> recent = new HashMap<>();

		for (Map.Entry<String, TaskProgress> entry : tracker.getProgress().entrySet())
		{
			TaskProgress state = entry.getValue();
			if (state.getSeen() != null)
			{
				unique.put(entry.getKey(), encode(state.getSeen()));
			}
			else if (state.getCount() > 0)
			{
				counts.put(entry.getKey(), state.getCount());
			}
			if (state.getXp() > 0)
			{
				xp.put(entry.getKey(), state.getXp());
			}
			if (state.getLastUpdated() > 0)
			{
				recent.put(entry.getKey(), state.getLastUpdated());
			}
		}

		configManager.setConfiguration(UnachievementsPlugin.CONFIG_GROUP, countsKey(accountHash), gson.toJson(counts));
		configManager.setConfiguration(UnachievementsPlugin.CONFIG_GROUP, xpKey(accountHash), gson.toJson(xp));
		configManager.setConfiguration(UnachievementsPlugin.CONFIG_GROUP, uniqueKey(accountHash), gson.toJson(unique));
		configManager.setConfiguration(UnachievementsPlugin.CONFIG_GROUP, recentKey(accountHash), gson.toJson(recent));
		configManager.setConfiguration(UnachievementsPlugin.CONFIG_GROUP, statsKey(accountHash),
			gson.toJson(tracker.getStats().getCounters()));
		writeSince(accountHash, tracker.getTrackingSince());
	}

	private void writeSince(long accountHash, long millis)
	{
		configManager.setConfiguration(UnachievementsPlugin.CONFIG_GROUP, sinceKey(accountHash),
			String.valueOf(millis));
	}

	private <T> Map<String, T> read(String key, Type type)
	{
		String json = configManager.getConfiguration(UnachievementsPlugin.CONFIG_GROUP, key);
		if (json == null || json.isEmpty())
		{
			return new HashMap<>();
		}
		try
		{
			Map<String, T> loaded = gson.fromJson(json, type);
			return loaded == null ? new HashMap<>() : loaded;
		}
		catch (Exception e)
		{
			log.warn("Failed to load Unachievements progress from {}", key, e);
			return new HashMap<>();
		}
	}

	private static String encode(BitSet set)
	{
		return Base64.getEncoder().encodeToString(set.toByteArray());
	}

	private static BitSet decode(String encoded)
	{
		try
		{
			return BitSet.valueOf(Base64.getDecoder().decode(encoded));
		}
		catch (IllegalArgumentException e)
		{
			log.warn("Discarding corrupt unique set", e);
			return new BitSet();
		}
	}
}

package com.tommyknight.unachievements;

import com.google.common.collect.ImmutableList;

/**
 * Every line on the Stats tab. Raw numbers, no jokes and no levelling.
 *
 * <p>Where a task already counts the thing, the stat reads that count rather than keeping a second
 * one. Only numbers no task measures get their own counter, which keeps the storage small and the
 * two tabs permanently in agreement.
 *
 * <p>Deliberately absent: experience, levels, quest points and anything else the game already puts
 * on a hiscores page. This tab is for the numbers nothing else bothers to keep.
 */
public final class StatRegistry
{
	public static final ImmutableList<Stat> STATS = ImmutableList.of(
		Stat.counter(StatCategory.MOVEMENT, "Tiles travelled", "tiles",
			TaskEventType.TILE_WALKED, null),
		Stat.counter(StatCategory.MOVEMENT, "Tiles walked", "tiles_walk",
			TaskEventType.TILE_WALKED, e -> "walk".equals(e.getText())),
		Stat.counter(StatCategory.MOVEMENT, "Tiles run", "tiles_run",
			TaskEventType.TILE_WALKED, e -> "run".equals(e.getText())),
		Stat.ofTask(StatCategory.MOVEMENT, "Teleports cast", "teleport"),
		Stat.ofTask(StatCategory.MOVEMENT, "Times out of energy", "energy"),

		// The three offensive numbers lead, in the order they answer questions: how much, how
		// often, and how often it came to nothing. Total hits counts every splat the player put
		// on something, misses included, so Hits missed reads as a share of the line above it.
		Stat.weighted(StatCategory.COMBAT, "Damage dealt", "damage_dealt",
			TaskEventType.DAMAGE_DEALT, null),
		Stat.counter(StatCategory.COMBAT, "Total hits", "hits_dealt",
			TaskEventType.DAMAGE_DEALT, null),
		Stat.ofTasks(StatCategory.COMBAT, "Hits missed", "whiff", "flub", "splash"),
		Stat.ofTask(StatCategory.COMBAT, "Damage taken", "ouch"),
		Stat.counter(StatCategory.COMBAT, "Hits taken", "hits_taken",
			TaskEventType.DAMAGE_TAKEN, e -> e.getValue() > 0),
		Stat.ofTask(StatCategory.COMBAT, "Hits blocked", "block"),
		Stat.ofTask(StatCategory.COMBAT, "Special attacks used", "spec"),
		Stat.counter(StatCategory.COMBAT, "Creatures killed", "kills",
			TaskEventType.NPC_KILLED, null),
		Stat.ofTask(StatCategory.COMBAT, "Chickens killed", "chickens"),
		Stat.ofTask(StatCategory.COMBAT, "Players attacked", "pvp"),
		Stat.ofTask(StatCategory.COMBAT, "Deaths", "dead"),
		Stat.ofTask(StatCategory.COMBAT, "Times poisoned", "poison"),
		Stat.ofTask(StatCategory.COMBAT, "Times envenomed", "venom"),

		// One experience drop is one successful action, which is the only thing that counts every
		// method: pay-dirt, stardust and anything washed rather than mined print nothing to chat.
		Stat.ofTask(StatCategory.SKILLS, "Logs chopped", "axeless"),
		Stat.ofTask(StatCategory.SKILLS, "Ore mined", "pickaxe"),
		Stat.ofTask(StatCategory.SKILLS, "Fish caught", "fish"),
		skillActions("Fires lit", "act_firemaking", "firemaking"),
		skillActions("Food cooked", "act_cooking", "cooking"),
		// Off the pickpocket message, not off Thieving experience, which also pays for stalls,
		// chests and lockpicking. A new counter id, because the old one was counting all of those.
		Stat.counter(StatCategory.SKILLS, "Pockets picked", "pockets",
			TaskEventType.CHAT_GAME, TaskRegistry::isPickpocket),
		Stat.ofTask(StatCategory.SKILLS, "Times caught", "thieving"),
		skillActions("Obstacles cleared", "act_agility", "agility"),
		skillActions("Items smithed", "act_smithing", "smithing"),
		skillActions("Items crafted", "act_crafting", "crafting"),
		skillActions("Items fletched", "act_fletching", "fletching"),
		skillActions("Runes crafted", "act_runecraft", "runecraft"),
		// Counted off the planting message, not off Farming experience. A new counter id rather
		// than the old one, because what that was accumulating was every Farming action at all.
		Stat.weighted(StatCategory.SKILLS, "Seeds planted", "seeds",
			TaskEventType.SEED_PLANTED, null),
		Stat.ofTask(StatCategory.SKILLS, "Herbs cleaned", "grimy"),
		Stat.ofTask(StatCategory.SKILLS, "Buckets of compost used", "compost"),
		skillActions("Creatures trapped", "act_hunter", "hunter"),

		Stat.ofTask(StatCategory.ITEMS, "Items dropped", "drop"),
		Stat.ofTask(StatCategory.ITEMS, "Items picked up", "loot"),
		Stat.ofTask(StatCategory.ITEMS, "Things eaten", "eat"),
		Stat.ofTask(StatCategory.ITEMS, "Potions drunk", "drink"),
		Stat.ofTask(StatCategory.ITEMS, "Cabbages eaten", "cabbage"),
		Stat.ofTask(StatCategory.ITEMS, "Beers drunk", "beer"),
		Stat.ofTask(StatCategory.ITEMS, "Bones buried", "bury"),
		Stat.counter(StatCategory.ITEMS, "Items alched", "alchs", TaskEventType.ALCH, null),
		Stat.ofTask(StatCategory.ITEMS, "Things examined", "examine"),
		Stat.ofTask(StatCategory.ITEMS, "Holes dug", "dig"),

		Stat.ofTask(StatCategory.WORLD, "Doors opened", "doors"),
		Stat.ofTask(StatCategory.WORLD, "Gates opened", "gates"),
		Stat.ofTask(StatCategory.WORLD, "Ladders climbed", "ladders"),
		Stat.ofTask(StatCategory.WORLD, "Staircases used", "stairs"),
		Stat.ofTask(StatCategory.WORLD, "Ditch crossings", "ditch"),
		Stat.ofTask(StatCategory.WORLD, "Fairy rings used", "fairyring"),
		Stat.ofTask(StatCategory.WORLD, "Spirit trees used", "spirittree"),
		Stat.ofTask(StatCategory.WORLD, "Webs slashed", "webs"),
		Stat.ofTask(StatCategory.WORLD, "Altars prayed at", "altar"),
		Stat.ofTask(StatCategory.WORLD, "Things searched", "search"),
		Stat.ofTask(StatCategory.WORLD, "Animals petted", "pet"),

		Stat.ofTask(StatCategory.INTERFACE, "Clicks", "clicks"),
		Stat.ofTask(StatCategory.INTERFACE, "Bank visits", "bank"),
		Stat.ofTask(StatCategory.INTERFACE, "World map opens", "worldmap"),
		Stat.ofTask(StatCategory.INTERFACE, "Camera spins", "spin"),
		Stat.ofTask(StatCategory.INTERFACE, "Zoom changes", "zoom"),
		Stat.ofTask(StatCategory.INTERFACE, "Prayers turned on", "prayer"),
		Stat.ofTask(StatCategory.INTERFACE, "Trades opened", "trade"),
		Stat.counter(StatCategory.INTERFACE, "Emotes performed", "emotes",
			TaskEventType.EMOTE_USED, null),
		Stat.ofTask(StatCategory.INTERFACE, "Public messages sent", "talk"),
		Stat.ofTask(StatCategory.INTERFACE, "Players followed", "conga"),
		Stat.ofTask(StatCategory.INTERFACE, "Music tracks played", "music")
	);

	static
	{
		// A stat pointing at a task that no longer exists renders zero forever and says nothing
		// about why, which is exactly what deleting a task invites. TaskRegistry already refuses
		// to build on a duplicate id; this is the other half of that guarantee. Failing here is
		// a programming error, caught on the first run after the edit and unreachable in a build
		// that ever started once.
		for (Stat stat : STATS)
		{
			if (stat.isOwnCounter())
			{
				continue;
			}
			for (String id : stat.getTaskIds())
			{
				if (TaskRegistry.byId(id) == null)
				{
					throw new IllegalStateException(
						"Stat \"" + stat.getLabel() + "\" references unknown task id \"" + id + "\"");
				}
			}
		}
	}

	/** Successful actions in a skill, counted off its experience drops. */
	private static Stat skillActions(String label, String counterId, String skill)
	{
		return Stat.counter(StatCategory.SKILLS, label, counterId, TaskEventType.SKILL_XP,
			e -> skill.equals(e.getText()));
	}

	private StatRegistry()
	{
	}
}

