	@Provides
	UnachievementsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(UnachievementsConfig.class);
	}

	@Override
	protected void startUp()
	{
		config = configManager.getConfig(UnachievementsConfig.class);
		// The skill baselines start at zero, which reads as a real total. Enabling the plugin while
		// already logged in would otherwise count one action on every experience driven task.
		resetDerivedState();
		tracker.setClock(client::getTickCount);
		tracker.setListeners(this::onUnlock, this::onLevel, this::onCountsChanged);
		// Mutes are not account scoped, so they load once here rather than with the progress.
		tracker.setMuted(progressStore.loadMuted());

		panel = injector.getInstance(UnachievementsPanel.class);
		panel.init(this);

		// Sorted by priority ascending, ties broken alphabetically on the tooltip. Four sits it
		// with Time Tracking, and loses the tie to it, so the order reads Time Tracking then
		// Unachievements.
		navButton = NavigationButton.builder()
			.tooltip("Unachievements")
			.icon(buildNavIcon())
			.priority(4)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		overlayManager.add(overlay);
		overlay.loadSprite();

		loadForCurrentAccount();
	}

	@Override
	protected void shutDown()
	{
		saveIfDirty();

		clientToolbar.removeNavigation(navButton);
		overlayManager.remove(overlay);
		overlay.clear();

		tracker.setListeners(null, null, null);
		tracker.reset();
		resetDerivedState();

		loadedAccountHash = -1;
		navButton = null;
		panel = null;
		config = null;
	}

	// Event translation. Every subscription in the plugin lives here and does nothing but flatten
	// a game event into a TaskEvent.

	@Subscribe(priority = -1)
	public void onMenuOpened(MenuOpened event)
	{
		ExamineMark mark = config.examineMark();
		if (mark == ExamineMark.OFF)
		{
			return;
		}

		for (MenuEntry entry : event.getMenuEntries())
		{
			markUnexamined(entry, mark);
		}
	}

	private void markUnexamined(MenuEntry entry, ExamineMark mark)
	{
		if (!"examine".equalsIgnoreCase(Text.removeTags(entry.getOption())))
		{
			return;
		}

		Task task;
		int id;

		if (entry.getItemId() != -1)
		{
			// Inventory and equipment, which arrive as component ops rather than item actions.
			task = TaskRegistry.byId("curator");
			id = entry.getItemId();
		}
		else if (entry.getType() == MenuAction.EXAMINE_OBJECT)
		{
			task = TaskRegistry.byId("antiquarian");
			id = entry.getIdentifier();
		}
		else if (entry.getType() == MenuAction.EXAMINE_NPC)
		{
			// The identifier is a scene index, so the creature has to name itself.
			task = TaskRegistry.byId("nosey");
			id = entry.getNpc() == null ? -1 : entry.getNpc().getId();
		}
		else if (entry.getType() == MenuAction.EXAMINE_ITEM_GROUND)
		{
			task = TaskRegistry.byId("curator");
			id = entry.getIdentifier();
		}
		else
		{
			return;
		}

		if (id >= 0 && !tracker.hasSeen(task, id))
		{
			entry.setOption(mark.apply(entry.getOption(), config.examineMarkColour()));
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		// Stripped of any mark this plugin put there, so a flagged Examine still matches the
		// filters. Colour and underline need no help: removeTags has already taken them.
		String option = ExamineMark.strip(
			Text.removeTags(event.getMenuOption()).toLowerCase());

		tracker.handle(TaskEvent.of(TaskEventType.MENU_CLICK, option));

		tracker.handle(TaskEvent.of(TaskEventType.MENU_TARGET,
			option + "|" + Text.removeTags(event.getMenuTarget()).toLowerCase()));

		// Emotes are identified by where the click landed rather than by the option, because the
		// option is the emote's own name and there are over forty of them. Checked here rather
		// than in classifyTarget so it does not depend on which menu action the tab happens to use.
		if (WidgetUtil.componentToInterface(event.getParam1()) == InterfaceID.EMOTE)
		{
			tracker.handle(TaskEvent.of(TaskEventType.EMOTE_USED, option));
		}

		classifyTarget(event, option);
	}

	/**
	 * Sorts a click into the item, object or NPC lane and republishes it with the thing's id
	 * attached. A dozen tasks want "which item did you drop" or "was that a door", and none of
	 * them can get it from the option text alone.
	 */
	private void classifyTarget(MenuOptionClicked event, String option)
	{
		MenuAction action = event.getMenuAction();
		switch (action)
		{
			case ITEM_FIRST_OPTION:
			case ITEM_SECOND_OPTION:
			case ITEM_THIRD_OPTION:
			case ITEM_FOURTH_OPTION:
			case ITEM_FIFTH_OPTION:
			case ITEM_USE:
			case EXAMINE_ITEM:
			case GROUND_ITEM_FIRST_OPTION:
			case GROUND_ITEM_SECOND_OPTION:
			case GROUND_ITEM_THIRD_OPTION:
			case GROUND_ITEM_FOURTH_OPTION:
			case GROUND_ITEM_FIFTH_OPTION:
			case EXAMINE_ITEM_GROUND:
				// A ground item names itself through the identifier. getItemId is for entries the
				// player is carrying, and comes back empty out here, which left every unique task
				// on this lane recording nothing at all.
				itemAction(event, option, event.getId());
				break;

			case CC_OP:
			case CC_OP_LOW_PRIORITY:
				// Inventory and equipment ops arrive as component ops. The ITEM_* actions above are
				// deprecated and never fire for them, which is why anything keyed off an inventory
				// click silently counted nothing. An entry with no item id is an ordinary interface
				// click, a spell or a tab, and is none of our business.
				if (event.getItemId() != -1)
				{
					itemAction(event, option, event.getItemId());
				}
				break;

			case GAME_OBJECT_FIRST_OPTION:
			case GAME_OBJECT_SECOND_OPTION:
			case GAME_OBJECT_THIRD_OPTION:
			case GAME_OBJECT_FOURTH_OPTION:
			case GAME_OBJECT_FIFTH_OPTION:
			case EXAMINE_OBJECT:
				String name = objectName(event.getId());
				tracker.handle(new TaskEvent(TaskEventType.OBJECT_ACTION,
					option + "|" + name, event.getId()));
				armTravel(name);
				break;

			case PLAYER_FIRST_OPTION:
			case PLAYER_SECOND_OPTION:
			case PLAYER_THIRD_OPTION:
			case PLAYER_FOURTH_OPTION:
			case PLAYER_FIFTH_OPTION:
			case PLAYER_SIXTH_OPTION:
			case PLAYER_SEVENTH_OPTION:
			case PLAYER_EIGHTH_OPTION:
				tracker.handle(TaskEvent.of(TaskEventType.PLAYER_ACTION, option));
				break;

			case NPC_FIRST_OPTION:
			case NPC_SECOND_OPTION:
			case NPC_THIRD_OPTION:
			case NPC_FOURTH_OPTION:
			case NPC_FIFTH_OPTION:
			case EXAMINE_NPC:
				tracker.handle(new TaskEvent(TaskEventType.NPC_ACTION, option, npcId(event)));
				break;

			case WIDGET_TARGET_ON_PLAYER:
				// The target names the item and the player both, which is enough for a filter to
				// pick out what was being waved around.
				tracker.handle(TaskEvent.of(TaskEventType.USED_ON_PLAYER,
					Text.removeTags(event.getMenuTarget()).toLowerCase()));
				break;

			case WIDGET_TARGET_ON_WIDGET:
				// Alchemy is a spell dragged onto an inventory item, so the target names the spell
				// and the item id names what is about to stop existing.
				if (Text.removeTags(event.getMenuTarget()).toLowerCase().contains("alchemy"))
				{
					tracker.handle(TaskEvent.of(TaskEventType.ALCH, event.getItemId()));
				}
				break;

			default:
				break;
		}
	}

	/** An option used on an item, wherever the click came from. */
	private void itemAction(MenuOptionClicked event, String option, int itemId)
	{
		tracker.handle(new TaskEvent(TaskEventType.ITEM_ACTION, option, itemId));

		// Deposits are remembered only while the bank is open, which is the window the task is
		// about: taking back something you put away moments ago.
		if (bankOpen)
		{
			if (option.startsWith("deposit"))
			{
				deposited.add(event.getItemId());
			}
			else if (option.startsWith("withdraw") && deposited.remove(event.getItemId()))
			{
				tracker.handle(TaskEvent.of(TaskEventType.BANK_YOYO, event.getItemId()));
			}
		}

		if ("eat".equals(option) || "drink".equals(option))
		{
			// Held back until an animation confirms it. Hitpoints are sampled now, before the food
			// heals, or nothing would ever look like a close call.
			pendingConsumeOption = option;
			pendingConsumeItemId = event.getItemId();
			pendingConsumeTick = client.getTickCount();
			pendingClutch = client.getBoostedSkillLevel(Skill.HITPOINTS) <= CLUTCH_HITPOINTS;
		}
	}

	/**
	 * Marks a transport as clicked. Nothing is counted yet: the click only opens the destination
	 * menu, and it opens whether or not the player then goes anywhere.
	 */
	/**
	 * Marks a fairy ring as clicked. Nothing is counted yet: the click only opens the
	 * destination menu, and it opens whether or not the player then goes anywhere.
	 *
	 * <p>Spirit trees are absent on purpose. They announce the trip in the chatbox, so they
	 * are confirmed there instead and arming them here as well would count each one twice.
	 */
	private void armTravel(String objectName)
	{
		if (!objectName.contains("fairy ring"))
		{
			return;
		}
		pendingTravel = "fairyring";
		pendingTravelTick = client.getTickCount();
	}

	/** Called when the player has jumped further than walking explains: the travel happened. */
	private void resolveTravel()
	{
		if (pendingTravel == null)
		{
			return;
		}

		String kind = pendingTravel;
		pendingTravel = null;

		if (client.getTickCount() - pendingTravelTick <= TRAVEL_WINDOW_TICKS)
		{
			tracker.handle(TaskEvent.of(TaskEventType.TRAVEL, kind));
		}
	}

	/**
	 * Scenery name for the tasks that can only be told apart by it, lowercased, never null.
	 *
	 * <p>The id always comes from a {@code GAME_OBJECT_*} menu action, so it is a real object and
	 * the lookup should always succeed. The guard stays because a name based task quietly matching
	 * nothing is a far better failure than the click handler throwing, and object definitions are
	 * patchy enough that this is not worth betting on.
	 */
	private String objectName(int objectId)
	{
		try
		{
			ObjectComposition definition = client.getObjectDefinition(objectId);
			if (definition == null || definition.getName() == null)
			{
				return "";
			}
			return definition.getName().toLowerCase();
		}
		catch (RuntimeException e)
		{
			return "";
		}
	}

	/**
	 * Menu entries identify NPCs by scene index, not by composition id. The entry resolves its own
	 * NPC against the world view it came from, which an index lookup against the top level view
	 * gets wrong inside an instance; the lookup stays only as a fallback.
	 */
	private int npcId(MenuOptionClicked event)
	{
		NPC npc = event.getMenuEntry().getNpc();
		if (npc == null)
		{
			npc = client.getTopLevelWorldView().npcs().byIndex(event.getId());
		}
		return npc == null ? -1 : npc.getId();
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (event.getActor() != client.getLocalPlayer())
		{
			return;
		}
		int animation = event.getActor().getAnimation();
		if (animation == -1)
		{
			return;
		}

		resolveConsume();

		if (TELEPORT_ANIMATIONS.contains(animation))
		{
			tracker.handle(TaskEvent.of(TaskEventType.TELEPORT, 0));
		}

		// No arming needed, unlike the other transports. This animation belongs to the ditch alone,
		// so its arrival is the whole confirmation, and the game decides when it plays.
		if (animation == AnimationID.WILD_DITCH_JUMP)
		{
			tracker.handle(TaskEvent.of(TaskEventType.DITCH_CROSSED));
		}
	}

	/**
	 * Turns a pending eat or drink click into a counted one, now that the player has visibly done
	 * it. Counting the click instead read about double: food has a cooldown and players click
	 * straight through it, so five sharks cost ten clicks.
	 *
	 * <p>Any animation is accepted rather than only {@code HUMAN_EAT}, because several potions and
	 * vial drinks have their own, and the click that queued this was already an eat or a drink.
	 */
	private void resolveConsume()
	{
		if (pendingConsumeOption == null)
		{
			return;
		}

		String option = pendingConsumeOption;
		pendingConsumeOption = null;

		if (client.getTickCount() - pendingConsumeTick > CONSUME_WINDOW_TICKS)
		{
			// Clicked, then something else happened first. Never eaten.
			return;
		}

		tracker.handle(new TaskEvent(TaskEventType.CONSUMED, option, pendingConsumeItemId));
		if (pendingClutch)
		{
			tracker.handle(TaskEvent.of(TaskEventType.CLUTCH_EAT, pendingConsumeItemId));
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		switch (event.getType())
		{
			// Dialogue arrives as "Speaker|Line". The speaker is stripped so a filter matches what
			// was actually said, and it gets its own type rather than joining the game messages:
			// NPC small talk is written for flavour and would trip filters meant for the client's
			// own output.
			case DIALOG:
				String line = Text.removeTags(event.getMessage());
				int speaker = line.indexOf('|');
				tracker.handle(TaskEvent.of(TaskEventType.CHAT_DIALOG,
					(speaker < 0 ? line : line.substring(speaker + 1)).toLowerCase()));
				break;

			case MESBOX:
				// The spirit tree says so itself, which beats arming on the click and waiting for the
				// player to move. Fairy rings print nothing comparable and keep the older route.
				String box = Text.removeTags(event.getMessage()).toLowerCase();
			if (box.contains("your vote has been received"))
			{
				// The submission, not the booth. Opening a poll loads its interface whether or
				// not anyone gets around to voting.
				tracker.handle(TaskEvent.of(TaskEventType.POLL_VOTED));
			}
			if (box.contains("dry tough bark"))
				{
					tracker.handle(TaskEvent.of(TaskEventType.TRAVEL, "spirittree"));
				}
				break;

			// ENGINE carries the messages the client prints itself rather than the server, which is
			// most of the complaints worth counting: "I can't reach that!" and friends.
			case GAMEMESSAGE:
			case ENGINE:
			case SPAM:
				String message = Text.removeTags(event.getMessage()).toLowerCase();
				tracker.handle(TaskEvent.of(TaskEventType.CHAT_GAME, message));
				trackPlanting(message);
				break;

			case PUBLICCHAT:
				Player local = client.getLocalPlayer();
				if (local != null && local.getName() != null
					&& Text.sanitize(event.getName()).equals(Text.sanitize(local.getName())))
				{
					tracker.handle(TaskEvent.of(TaskEventType.CHAT_PUBLIC_SELF,
						Text.removeTags(event.getMessage())));
				}
				break;

			default:
				break;
		}
	}

	/**
	 * Counts seeds going into the ground, off the line the game prints when they do.
	 *
	 * <p>The message names the number for a multi seed patch, "You plant 3 potato seeds in the
	 * allotment", and spells it as an article for a single one, "You plant a guam seed in the herb
	 * patch". No digits therefore means one seed, not none.
	 */
	private void trackPlanting(String message)
	{
		if (!message.startsWith(PLANT_PREFIX))
		{
			return;
		}

		// Only digits sitting immediately after the prefix are the count. Scanning the rest of the
		// line for a number would pick up whatever else happened to contain one.
		int seeds = 0;
		for (int i = PLANT_PREFIX.length(); i < message.length(); i++)
		{
			char c = message.charAt(i);
			if (c < '0' || c > '9')
			{
				break;
			}
			seeds = seeds * 10 + (c - '0');
		}

		tracker.handle(TaskEvent.of(TaskEventType.SEED_PLANTED, Math.max(1, seeds)));
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (event.getActor() == client.getLocalPlayer())
		{
			tracker.handle(TaskEvent.of(TaskEventType.DAMAGE_TAKEN, event.getHitsplat().getAmount()));
			return;
		}

		if (!event.getHitsplat().isMine())
		{
			return;
		}

		int dealt = event.getHitsplat().getAmount();

		if (specTick >= 0)
		{
			specSplats++;
			specLanded |= dealt > 0;
		}
		tracker.handle(TaskEvent.of(TaskEventType.DAMAGE_DEALT, dealt));

		// A splashed spell shows a zero splat as well as the splash graphic, so counting both here
		// would have every failed cast land on two tasks at once. Magic misses belong to SPLASH.
		if (dealt == 0 && !STYLE_MAGIC.equals(combatStyle))
		{
			tracker.handle(TaskEvent.of(TaskEventType.ZERO_HIT_DEALT, combatStyle));
		}
	}

	@Subscribe
	public void onGraphicChanged(GraphicChanged event)
	{
		if (event.getActor() == client.getLocalPlayer())
		{
			return;
		}
		// Gated on the style as well as the graphic. The spot anim alone is not proof the local
		// player cast anything: it shows on a target splashed by whoever else is attacking it.
		if (STYLE_MAGIC.equals(combatStyle) && event.getActor().hasSpotAnim(SPLASH_GRAPHIC))
		{
			tracker.handle(TaskEvent.of(TaskEventType.SPLASH));
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		Player local = client.getLocalPlayer();
		if (event.getActor() == local)
		{
			tracker.handle(TaskEvent.of(TaskEventType.DEATH));
			return;
		}

		// Only kills we were actually involved in. Anything else is someone else's business.
		if (event.getActor() instanceof NPC && local != null && event.getActor().getInteracting() == local)
		{
			tracker.handle(TaskEvent.of(TaskEventType.NPC_KILLED, ((NPC) event.getActor()).getId()));
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			bankOpen = true;
			tracker.handle(TaskEvent.of(TaskEventType.BANK_OPENED));
		}
		else if (event.getGroupId() == InterfaceID.WORLDMAP)
		{
			tracker.handle(TaskEvent.of(TaskEventType.WORLD_MAP_OPENED));
		}
		else if (event.getGroupId() == InterfaceID.TRADEMAIN)
		{
			tracker.handle(TaskEvent.of(TaskEventType.TRADE_OPENED));
		}
	}

	/**
	 * One event per experience drop. Gathering skills print nothing to the chatbox for a successful
	 * action, and the messages that do exist miss whole methods: motherlode pay-dirt, stardust and
	 * anything washed rather than mined. An xp drop catches all of them.
	 */
	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		int index = event.getSkill().ordinal();
		int previousXp = lastSkillXp[index];
		lastSkillXp[index] = event.getXp();

		// Keep taking the baseline through the settling window, but do not count any of it. The
		// first report per skill is the running total from login rather than a gain, and on some
		// logins there are two.
		if (skillSettleTicks > 0 || previousXp < 0 || event.getXp() <= previousXp)
		{
			return;
		}

		tracker.handle(new TaskEvent(TaskEventType.SKILL_XP,
			event.getSkill().getName().toLowerCase(), event.getXp() - previousXp));
	}

	/** The special attack bar only falls when a special is used; it regenerates upwards. */
	private void trackSpecialAttack()
	{
		int energy = client.getVarpValue(VarPlayerID.SA_ENERGY);
		if (lastSpecialEnergy != -1 && energy < lastSpecialEnergy)
		{
			tracker.handle(TaskEvent.of(TaskEventType.SPECIAL_ATTACK));
		specTick = client.getTickCount();
		specSplats = 0;
		specLanded = false;
		}
		lastSpecialEnergy = energy;
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			bankOpen = false;
			deposited.clear();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		// Varbits change constantly, and none of the work below is free: the prayer sweep alone
		// reads every prayer varbit in the game. Each branch is gated on the thing it actually
		// reads, which is why the baselines are seeded on login instead of by the first change
		// that happened to arrive.
		if (PRAYER_VARBITS.contains(event.getVarbitId()))
		{
			trackPrayers();
		}

		if (event.getVarpId() == VarPlayerID.SA_ENERGY)
		{
			trackSpecialAttack();
		}

		if (event.getVarpId() == VarPlayerID.POISON)
		{
			trackPoison(event.getValue());
		}

		if (event.getVarpId() == VarPlayerID.COM_MODE
			|| event.getVarbitId() == VarbitID.COMBAT_WEAPON_CATEGORY
			|| event.getVarbitId() == VarbitID.AUTOCAST_DEFMODE)
		{
			updateCombatStyle();
		}
	}

	/**
	 * Works out whether the player is currently meleeing, ranging or casting.
	 *
	 * <p>Follows the same path the game does: the weapon category selects a list of stances, the
	 * selected stance is a struct, and the struct names the style. Reading the name rather than the
	 * category means a new weapon type is classified correctly the day it is added, with no change
	 * here.
	 */
	private void updateCombatStyle()
	{
		int weaponType = client.getVarbitValue(VarbitID.COMBAT_WEAPON_CATEGORY);
		int slot = client.getVarpValue(VarPlayerID.COM_MODE);

		int styleEnum = client.getEnum(EnumID.WEAPON_STYLES).getIntValue(weaponType);
		if (styleEnum == -1)
		{
			// Weapons with hand written stance lists, the blue moon spear and the partisan. Only
			// the spear reaches slot 4, and when it does it is casting.
			combatStyle = slot >= FIRST_CASTING_SLOT ? STYLE_MAGIC : STYLE_MELEE;
			return;
		}

		// Defensive casting is not its own stance. It is slot 4 plus the casting mode.
		if (slot == FIRST_CASTING_SLOT)
		{
			slot += client.getVarbitValue(VarbitID.AUTOCAST_DEFMODE);
		}

		int[] stances = client.getEnum(styleEnum).getIntVals();
		if (slot < 0 || slot >= stances.length)
		{
			combatStyle = STYLE_MELEE;
			return;
		}

		StructComposition stance = client.getStructComposition(stances[slot]);
		String name = stance.getStringValue(ParamID.ATTACK_STYLE_NAME);
		combatStyle = bucket(name == null ? "" : name.toLowerCase(), slot);
	}

	/** Collapses the seven stance names the game uses into the three that matter here. */
	private static String bucket(String styleName, int slot)
	{
		switch (styleName)
		{
			case "ranging":
			case "longrange":
				return STYLE_RANGED;
			case "casting":
				return STYLE_MAGIC;
			case "defensive":
				// A staff's defensive casting stance is also named "Defensive", and only its slot
				// tells it apart from a melee weapon's defensive stance.
				return slot >= FIRST_CASTING_SLOT ? STYLE_MAGIC : STYLE_MELEE;
			default:
				return STYLE_MELEE;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (skillSettleTicks > 0)
		{
			skillSettleTicks--;
		}

		resolveSpec();
		trackPrayerPoints();
		trackMovement();
		trackIdle();
		trackRunEnergy();
		flushPanel();
		saveIfDue();
	}

	/**
	 * Redraws the sidebar at most once a tick, and not at all when it is not on screen.
	 *
	 * <p>Every counter movement used to rebuild the whole list on the spot. Running fires two tile
	 * events a tick and each one queued its own pass, so the panel was being torn down and rebuilt
	 * several times a second for something nobody was looking at.
	 */
	private void flushPanel()
	{
		if (!panelDirty || panel == null || !panel.isShowing())
		{
			// Left dirty on purpose when hidden, so opening the sidebar picks it up next tick.
			return;
		}
		panelDirty = false;
		panel.refresh();
	}

	/** Config writes are cheap but not free, and nothing here needs saving to the exact tick. */
	private void saveIfDue()
	{
		if (!dirty)
		{
			ticksSinceSave = 0;
			return;
		}
		if (++ticksSinceSave < SAVE_INTERVAL_TICKS)
		{
			return;
		}
		ticksSinceSave = 0;
		saveIfDirty();
	}

	/**
	 * One event per tile of ground covered, flagged only when the player walked it, on foot and
	 * with no boots. Running is excluded deliberately: covering ground barefoot should be slow.
	 */
	private void trackMovement()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}

		WorldPoint here = local.getWorldLocation();
		if (here == null || lastLocation == null)
		{
			return;
		}

		if (here.getPlane() != lastLocation.getPlane()
			|| here.distanceTo(lastLocation) > MAX_STEP)
		{
			// Further than walking explains, so the player was moved rather than moving. This is
			// also the only honest confirmation that a transport was actually used.
			resolveTravel();
			return;
		}

		int tiles = here.distanceTo(lastLocation);
		if (tiles <= 0)
		{
			return;
		}

		String gait = client.getVarpValue(VarPlayerID.OPTION_RUN) == 1 ? "run" : "walk";
		int barefoot = isBarefoot() ? 1 : 0;
		for (int i = 0; i < tiles; i++)
		{
			tracker.handle(new TaskEvent(TaskEventType.TILE_WALKED, gait, barefoot));
		}
	}

	/**
	 * Decides whether the special attack that just went off achieved anything.
	 *
	 * <p>No hitsplats at all means it never reached anything, which is a different kind of
	 * failure and deliberately not counted here.
	 */
	private void resolveSpec()
	{
		if (specTick < 0 || client.getTickCount() - specTick < SPEC_WINDOW_TICKS)
		{
			return;
		}

		if (specSplats > 0 && !specLanded)
		{
			tracker.handle(TaskEvent.of(TaskEventType.SPEC_MISSED));
		}
		specTick = -1;
	}

	/** Fires once when prayer runs dry, not for every tick spent sitting at zero. */
	private void trackPrayerPoints()
	{
		int points = client.getBoostedSkillLevel(Skill.PRAYER);
		if (lastPrayerPoints > 0 && points == 0)
		{
			tracker.handle(TaskEvent.of(TaskEventType.PRAYER_EMPTY));
		}
		lastPrayerPoints = points;
	}

	private boolean isBarefoot()
	{
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		return worn == null || worn.getItem(EquipmentInventorySlot.BOOTS.getSlotIdx()) == null;
	}

	/**
	 * Counts prayers switched on, not changes to the set.
	 *
	 * <p>A change counter read wrong twice over: one flick is an on and an off, so it scored two,
	 * while quick prayers lighting three prayers at once still only scored one. Counting the bits
	 * that went from off to on makes the number mean exactly what the task says it does.
	 */
	private void trackPrayers()
	{
		int mask = 0;
		int bit = 1;
		for (Prayer prayer : Prayer.values())
		{
			if (client.isPrayerActive(prayer))
			{
				mask |= bit;
			}
			bit <<= 1;
		}

		if (lastPrayerMask != -1)
		{
			int switchedOn = Integer.bitCount(mask & ~lastPrayerMask);
			if (switchedOn > 0)
			{
				tracker.handle(TaskEvent.of(TaskEventType.PRAYER_TOGGLE, switchedOn));
			}
		}
		lastPrayerMask = mask;
	}

	/**
	 * The poison varp doubles as the venom varp: positive values are poison damage, and anything
	 * at or below the venom threshold is venom.
	 */
	private void trackPoison(int value)
	{
		if (lastPoison == Integer.MIN_VALUE)
		{
			lastPoison = value;
			return;
		}

		boolean wasPoisoned = lastPoison > 0;
		boolean wasVenomed = lastPoison >= VENOM_THRESHOLD;
		lastPoison = value;

		if (value >= VENOM_THRESHOLD && !wasVenomed)
		{
			tracker.handle(TaskEvent.of(TaskEventType.VENOMED));
		}
		else if (value > 0 && value < VENOM_THRESHOLD && !wasPoisoned)
		{
			tracker.handle(TaskEvent.of(TaskEventType.POISONED));
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		// Sampled per client tick rather than per game tick, or a fast spin aliases past 180
		// degrees between samples and reads as a turn in the wrong direction.
		trackCameraSpin();
		trackCameraZoom();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			// Also armed here, not only in resetDerivedState. A reconnect goes straight back to
			// LOGGED_IN without passing the login screen, and still replays every skill.
			skillSettleTicks = SKILL_SETTLE_TICKS;
			updateCombatStyle();
			// Baselines have to be taken here now that the varbit handler is gated. They used to
			// be seeded by whatever varbit changed first, which was always something harmless
			// arriving before the player could act; with the gate, the first thing to seed them
			// would be the player's own first prayer or first special, and it would not count.
			trackPrayers();
			trackSpecialAttack();
			loadForCurrentAccount();
			if (!announcedLogin)
			{
				announcedLogin = true;
				tracker.handle(TaskEvent.of(TaskEventType.LOGIN));
			}
		}
		else if (state == GameState.HOPPING)
		{
			tracker.handle(TaskEvent.of(TaskEventType.WORLD_HOP));
			saveIfDirty();
			resetDerivedState();
		}
		else if (state == GameState.LOGIN_SCREEN)
		{
			announcedLogin = false;
			saveIfDirty();
			resetDerivedState();
		}
	}

	private void trackIdle()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			idleTicks = 0;
			return;
		}

		WorldPoint here = local.getWorldLocation();
		boolean still = here != null && here.equals(lastLocation) && local.getAnimation() == -1;
		lastLocation = here;

		if (!still)
		{
			idleTicks = 0;
			return;
		}

		// Counts the bout, not its length. The counter is left parked above the threshold so an
		// afk session fires once and then stays quiet until something moves.
		if (idleTicks < IDLE_TICK_THRESHOLD && ++idleTicks == IDLE_TICK_THRESHOLD)
		{
			tracker.handle(TaskEvent.of(TaskEventType.IDLE_PERIOD));
		}
	}

	private void trackRunEnergy()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		int energy = client.getEnergy();
		if (lastEnergy > 0 && energy == 0)
		{
			tracker.handle(TaskEvent.of(TaskEventType.RUN_EMPTY));
		}
		lastEnergy = energy;
	}

	/**
	 * One event per settled zoom change rather than per notch, or a single scroll of the wheel
	 * would count as a dozen.
	 */
	private void trackCameraZoom()
	{
		int scale = client.getScale();
		if (lastScale == -1)
		{
			lastScale = scale;
			return;
		}
		if (scale != lastScale)
		{
			lastScale = scale;
			zoomSettleTicks = 0;
			zoomPending = true;
		}
		else if (zoomPending && ++zoomSettleTicks >= ZOOM_SETTLE_TICKS)
		{
			zoomPending = false;
			tracker.handle(TaskEvent.of(TaskEventType.CAMERA_ZOOM));
		}
	}

	private void trackCameraSpin()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		int yaw = client.getCameraYaw();
		if (lastYaw == -1)
		{
			lastYaw = yaw;
			return;
		}

		// Shortest signed distance around the 0..2047 circle.
		int delta = ((yaw - lastYaw + FULL_TURN + FULL_TURN / 2) % FULL_TURN) - FULL_TURN / 2;
		lastYaw = yaw;

		yawAccumulator += Math.abs(delta);
		while (yawAccumulator >= FULL_TURN)
		{
			yawAccumulator -= FULL_TURN;
			tracker.handle(TaskEvent.of(TaskEventType.CAMERA_SPIN));
		}
	}

	// Unlock presentation

	private void onUnlock(Unlock unlock)
	{
		// Banking fires a burst of counters at once and the popup lands square over the interface.
		// Dropped rather than queued: holding them back only means a stack of them the moment the
		// bank closes. The chat line still records it either way.
		if (config.showPopup() && !bankOpen)
		{
			overlay.enqueue(unlock);
		}

		if (config.showChatMessage())
		{
			// Just the sentence, no tag. The popup already says which task and which tier, so the
			// bracket was repeating the plugin's own name into every line for no one's benefit.
			//
			// "You have petted 6 animals."
			chat(unlock.getFlavour());
		}

		if (config.playSound())
		{
			client.playSoundEffect(SoundEffectID.TOWN_CRIER_BELL_DING);
		}
	}

	/**
	 * A task gained a level that was not also a new tier. Chat only, and only when the player has
	 * asked for that much of it. There is no popup and no sound: at this rate either would stop
	 * being an event and start being weather.
	 */
	private void onLevel(Task task, int level)
	{
		if (config.showChatMessage() && config.chatFrequency() == ChatFrequency.LEVEL)
		{
			chat(task.getName() + " is now level " + level + ".");
		}
	}

	private void chat(String text)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(new ChatMessageBuilder().append(config.chatColour(), text).build())
			.build());
	}

	/**
	 * Silences or unsilences one task. Written through immediately: there is no batching to be had
	 * from a setting the player changes by hand once in a while.
	 */
	void toggleMute(Task task)
	{
		tracker.toggleMuted(task);
		progressStore.saveMuted(tracker.getMuted());
	}

	// Persistence

	private void loadForCurrentAccount()
	{
		long accountHash = client.getAccountHash();
		if (accountHash == -1 || accountHash == loadedAccountHash)
		{
			return;
		}

		saveIfDirty();
		progressStore.load(accountHash, tracker);
		loadedAccountHash = accountHash;
		dirty = false;
		refreshPanel();
	}

	private void saveIfDirty()
	{
		if (!dirty || loadedAccountHash == -1)
		{
			return;
		}
		progressStore.save(loadedAccountHash, tracker);
		dirty = false;
	}

	void resetProgress()
	{
		tracker.reset();
		// reset() clears the date along with everything else, so the clock restarts from here.
		tracker.setTrackingSince(System.currentTimeMillis());
		if (loadedAccountHash != -1)
		{
			progressStore.save(loadedAccountHash, tracker);
		}
		dirty = false;
		overlay.clear();
		refreshPanel();
	}

	/** Tracker callback: counts moved, so the save is stale and the sidebar is out of date. */
	private void onCountsChanged()
	{
		dirty = true;
		panelDirty = true;
	}

	private void refreshPanel()
	{
		if (panel != null)
		{
			panel.refresh();
		}
	}

	private void resetDerivedState()
	{
		lastLocation = null;
		idleTicks = 0;
		lastEnergy = -1;
		lastYaw = -1;
		yawAccumulator = 0;
		lastPrayerMask = -1;
		lastPoison = Integer.MIN_VALUE;
		lastScale = -1;
		zoomPending = false;
		zoomSettleTicks = 0;
		pendingConsumeOption = null;
		pendingConsumeTick = 0;
		pendingTravel = null;
		pendingTravelTick = 0;
		pendingClutch = false;
		bankOpen = false;
		deposited.clear();
		lastPrayerPoints = -1;
		specTick = -1;
		lastSpecialEnergy = -1;
		combatStyle = STYLE_MELEE;
		java.util.Arrays.fill(lastSkillXp, -1);
		// GameTick only fires in world, so this counts down from arrival rather than from the click
		// on the login button. Three is comfortably past the second experience report.
		skillSettleTicks = SKILL_SETTLE_TICKS;
	}

	/**
	 * Nav icon: a dragon med helm, the top of the tier ladder and the same object the header and
	 * every popup already show.
	 *
	 * <p>The horns carry the whole identification. A bare red dome at this size is a woolly hat,
	 * so they are drawn first and deliberately chunky: thinner ones are more faithful to the item
	 * but disappear entirely at sixteen pixels, which defeats the point of the icon.
	 */
	private static BufferedImage buildNavIcon()
	{
		BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		// Horns first, so the dome overlaps their roots and they read as growing out of it. They
		// taper to a point rather than ending flat: a flat wedge reads as a wing at this size.
		g.setColor(ICON_HORN);
		g.fillPolygon(new int[]{5, 0, 5}, new int[]{4, 2, 10}, 3);
		g.fillPolygon(new int[]{11, 16, 11}, new int[]{4, 2, 10}, 3);
		g.setColor(ICON_HORN_DARK);
		g.drawLine(0, 2, 4, 8);
		g.drawLine(16, 2, 12, 8);

		// Dome over straight sides. The highlight down the left is what stops it looking like a
		// flat sticker, and the outline stops the lower half melting into a dark sidebar.
		g.setColor(ICON_BODY);
		g.fillArc(3, 2, 10, 11, 0, 180);
		g.fillRect(3, 7, 10, 7);

		g.setColor(ICON_LIT);
		g.fillArc(4, 3, 5, 8, 40, 120);

		g.setColor(ICON_DARK);
		g.fillRect(3, 12, 10, 2);
		g.drawArc(3, 2, 10, 11, 0, 180);
		g.drawLine(3, 7, 3, 13);
		g.drawLine(12, 7, 12, 13);

		// Nasal bar under a brow slit. Kept small on purpose: at six pixels wide the slit stopped
		// being a visor and became a black cross with a helm around it.
		g.setColor(ICON_VISOR);
		g.fillRect(7, 7, 2, 5);
		g.fillRect(5, 7, 6, 1);

		g.dispose();
		return img;
	}
}

package com.tommyknight.unachievements;

import java.awt.Color;
import lombok.Getter;
import net.runelite.api.gameval.ItemID;

/**
 * The eight metal tiers, keyed to level using the game's own armour requirements. Bronze and Iron
 * are both level 1 in game; Iron is nudged to 2 here so the two are distinguishable.
 *
 * <p>Tiers are a display band over the level, not the unit of progress. Reaching Dragon at level
 * 60 means the last 39 levels all sit in one tier, which is deliberate: the tiers are the hook
 * and arrive quickly, the levels are the long tail.
 *
 * <p>Each tier also multiplies experience earned, so an action worth 10 xp at Bronze is worth 30
 * at Dragon. That is what keeps 99 merely absurd rather than impossible, and it is why experience
 * has to be stored rather than derived from the action count.
 */
@Getter
public enum Tier
{
	BRONZE("Bronze", 1, 1.0f, new Color(0xCD7F32), ItemID.BRONZE_FULL_HELM, ItemID.BRONZE_DAGGER),
	IRON("Iron", 2, 1.2f, new Color(0x8A8A8A), ItemID.IRON_FULL_HELM, ItemID.IRON_DAGGER),
	STEEL("Steel", 5, 1.4f, new Color(0xB8C4CC), ItemID.STEEL_FULL_HELM, ItemID.STEEL_DAGGER),
	BLACK("Black", 10, 1.6f, new Color(0x5A5A66), ItemID.BLACK_FULL_HELM, ItemID.BLACK_DAGGER),
	MITHRIL("Mithril", 20, 1.9f, new Color(0x6E63C8), ItemID.MITHRIL_FULL_HELM, ItemID.MITHRIL_DAGGER),
	ADAMANT("Adamant", 30, 2.2f, new Color(0x4E8F63), ItemID.ADAMANT_FULL_HELM, ItemID.ADAMANT_DAGGER),
	RUNE("Rune", 40, 2.5f, new Color(0x4FA0C8), ItemID.RUNE_FULL_HELM, ItemID.RUNE_DAGGER),
	// Dragon uses the med helm rather than the full helm: it is the more recognisable of the two.
	DRAGON("Dragon", 60, 3.0f, new Color(0xC4402F), ItemID.DRAGON_MED_HELM, ItemID.DRAGON_DAGGER);

	/** Sidebar panel background, the base the row tints are mixed into. */
	private static final Color PANEL_BASE = new Color(30, 30, 30);

	/** How much of the tier colour bleeds into a row background. Subtle on purpose. */
	private static final float TINT_STRENGTH = 0.16f;

	private final String displayName;

	/** Level at which this tier is reached. Also doubles as the minimum action count, below. */
	private final int levelRequirement;

	/** Multiplier applied to experience earned while sitting at this tier. */
	private final float xpMultiplier;

	/** Row tint only. Never used for text; several of these are unreadable as a font colour. */
	private final Color color;

	private final int helmItemId;
	private final int daggerItemId;

	/** Lazily computed: enum constants are built before the enum's own static fields exist. */
	private Color background;

	Tier(String displayName, int levelRequirement, float xpMultiplier, Color color,
		int helmItemId, int daggerItemId)
	{
		this.displayName = displayName;
		this.levelRequirement = levelRequirement;
		this.xpMultiplier = xpMultiplier;
		this.color = color;
		this.helmItemId = helmItemId;
		this.daggerItemId = daggerItemId;
	}

	public Color getBackground()
	{
		if (background == null)
		{
			background = tint(color);
		}
		return background;
	}

	private static Color tint(Color color)
	{
		return new Color(
			Math.round(PANEL_BASE.getRed() + (color.getRed() - PANEL_BASE.getRed()) * TINT_STRENGTH),
			Math.round(PANEL_BASE.getGreen() + (color.getGreen() - PANEL_BASE.getGreen()) * TINT_STRENGTH),
			Math.round(PANEL_BASE.getBlue() + (color.getBlue() - PANEL_BASE.getBlue()) * TINT_STRENGTH));
	}

	public Tier next()
	{
		int i = ordinal() + 1;
		return i < values().length ? values()[i] : null;
	}

	/** Highest tier the given level qualifies for. Never null; level 1 is Bronze. */
	public static Tier forLevel(int level)
	{
		Tier best = BRONZE;
		for (Tier tier : values())
		{
			if (level >= tier.levelRequirement)
			{
				best = tier;
			}
		}
		return best;
	}

	/**
	 * The anti skip guard, for experience based tasks only. A task cannot show a tier it has not
	 * also done the raw actions for, reusing the level requirements as action counts: two actions
	 * for Iron, five for Steel, and so on.
	 *
	 * <p>Linear tasks are deliberately exempt. Their level is already a proportion of a known
	 * target, so the pacing is built in, and applying an absolute action floor to a task with a
	 * small target caps it permanently: a twenty two item collection would sit at Mithril at 22
	 * of 22, despite being level 99.
	 */
	public static Tier effective(int level, int count, boolean guarded)
	{
		Tier byLevel = forLevel(level);
		if (!guarded)
		{
			return byLevel;
		}
		Tier byCount = forLevel(count);
		return byLevel.ordinal() <= byCount.ordinal() ? byLevel : byCount;
	}
}

package com.tommyknight.unachievements;

/**
 * The OSRS experience curve, levels 1 to 99.
 *
 * <p>Computed from Jagex's formula rather than transcribed, so there is nothing to get wrong:
 * each level adds {@code floor(lvl + 300 * 2^(lvl/7))} to a running total, and the requirement
 * for the next level is a quarter of it. Level 99 lands on 13,034,431.
 */
final class XpTable
{
	static final int MAX_LEVEL = 99;

	/** Indexed by level, so {@code XP_FOR_LEVEL[99]} is the cost of 99. Index 0 is unused. */
	private static final int[] XP_FOR_LEVEL = new int[MAX_LEVEL + 1];

	static
	{
		double points = 0;
		for (int level = 1; level < MAX_LEVEL; level++)
		{
			points += Math.floor(level + 300 * Math.pow(2, level / 7.0));
			XP_FOR_LEVEL[level + 1] = (int) Math.floor(points / 4);
		}
	}

	static int xpForLevel(int level)
	{
		if (level <= 1)
		{
			return 0;
		}
		return XP_FOR_LEVEL[Math.min(level, MAX_LEVEL)];
	}

	/**
	 * Highest level the given experience pays for.
	 *
	 * <p>Binary search rather than a scan. This runs far more than it looks: the panel calls it
	 * per row and again inside the sort comparator, and every counted event reaches it once per
	 * task while working out the overall rank. A scan spent most of that walking past levels no
	 * task had reached.
	 *
	 * <p>Hand rolled rather than {@link java.util.Arrays#binarySearch}, which would need the
	 * argument narrowed to {@code int}. Stored experience keeps climbing after 99, so that cast
	 * would eventually overflow and report a nonsense level.
	 */
	static int levelForXp(long xp)
	{
		int low = 2;
		int high = MAX_LEVEL;
		int best = 1;

		while (low <= high)
		{
			int mid = (low + high) >>> 1;
			if (xp >= XP_FOR_LEVEL[mid])
			{
				best = mid;
				low = mid + 1;
			}
			else
			{
				high = mid - 1;
			}
		}
		return best;
	}

	/**
	 * How far through the current level the given experience is, 0 to 1. Returns 1 at 99, where
	 * there is no next level to be partway to.
	 */
	static float progressThroughLevel(long xp)
	{
		int level = levelForXp(xp);
		if (level >= MAX_LEVEL)
		{
			return 1f;
		}
		int floor = xpForLevel(level);
		int ceiling = xpForLevel(level + 1);
		return (xp - floor) / (float) (ceiling - floor);
	}

	private XpTable()
	{
	}
}

package com.tommyknight.unachievements;

import java.util.function.Predicate;
import javax.annotation.Nullable;
import lombok.Getter;

/**
 * One line on the Stats tab. A plain running total, with none of the levelling a {@link Task}
 * carries.
 *
 * <p>A stat comes from one of two places. Most mirror a task's count, which costs no storage and
 * makes it impossible for the two tabs to disagree. The rest keep their own counter, for numbers
 * no task measures: tiles run, damage dealt, creatures killed.
 */
@Getter
public class Stat
{
	private final StatCategory category;
	private final String label;

	/**
	 * Tasks whose counts this adds up. Null when the stat keeps its own counter. Usually one, but
	 * a stat is free to roll several together where the split matters on the Tasks tab and not
	 * here: three kinds of miss are three tasks and one number.
	 */
	@Nullable
	private final String[] taskIds;

	/** Storage key for a stat that counts for itself. Null when it mirrors a task. */
	@Nullable
	private final String counterId;

	@Nullable
	private final TaskEventType trigger;

	@Nullable
	private final Predicate<TaskEvent> filter;

	/** Counts the event's value rather than the event, as damage dealt does. */
	private final boolean weighted;

	private Stat(StatCategory category, String label, @Nullable String[] taskIds,
		@Nullable String counterId, @Nullable TaskEventType trigger,
		@Nullable Predicate<TaskEvent> filter, boolean weighted)
	{
		this.category = category;
		this.label = label;
		this.taskIds = taskIds;
		this.counterId = counterId;
		this.trigger = trigger;
		this.filter = filter;
		this.weighted = weighted;
	}

	/** A stat that reads an existing task's count. */
	static Stat ofTask(StatCategory category, String label, String taskId)
	{
		return new Stat(category, label, new String[]{taskId}, null, null, null, false);
	}

	/** A stat that adds several tasks' counts together. */
	static Stat ofTasks(StatCategory category, String label, String... taskIds)
	{
		return new Stat(category, label, taskIds, null, null, null, false);
	}

	/** A stat with its own counter, fed off the event stream. */
	static Stat counter(StatCategory category, String label, String counterId,
		TaskEventType trigger, @Nullable Predicate<TaskEvent> filter)
	{
		return new Stat(category, label, null, counterId, trigger, filter, false);
	}

	/** A counter measured in the event value: damage rather than hits. */
	static Stat weighted(StatCategory category, String label, String counterId,
		TaskEventType trigger, @Nullable Predicate<TaskEvent> filter)
	{
		return new Stat(category, label, null, counterId, trigger, filter, true);
	}

	boolean isOwnCounter()
	{
		return counterId != null;
	}

	boolean matches(TaskEvent event)
	{
		return event.getType() == trigger && (filter == null || filter.test(event));
	}

	/** How much one event moves this stat by. */
	int incrementFor(TaskEvent event)
	{
		return weighted ? Math.max(0, event.getValue()) : 1;
	}

	/** Renders a raw total for display. */
	String render(long value)
	{
		return String.format("%,d", value);
	}
}

package com.tommyknight.unachievements;

import java.util.EnumSet;
import java.util.Set;

/**
 * The raw game facts the plugin reports. These describe what happened, never what it means -
 * naming a type after a task ("CHOPPED_WITHOUT_AXE") would tie the event layer to the content
 * layer and defeat the point of having one.
 *
 * <p>The three ACTION types are deliberately broad. Carrying the menu option in {@code text} and
 * the thing's id in {@code value} lets a dozen tasks share one subscription and one translation,
 * with the registry doing the narrowing.
 */
public enum TaskEventType
{
	/** Any menu option the player clicked. text = the option, lowercased. */
	MENU_CLICK,

	/** An option used on another player. text = the option lowercased. */
	PLAYER_ACTION,

	/** An option used on an item. text = the option lowercased, value = item id. */
	ITEM_ACTION,

	/**
	 * An option used on scenery. text = "option|name", both lowercased, value = object id. The
	 * name is carried because doors, gates, ladders and staircases are only distinguishable by it.
	 */
	OBJECT_ACTION,

	/** An option used on an NPC. text = the option lowercased, value = npc id. */
	NPC_ACTION,

	/** An NPC the player was fighting died. value = npc id. */
	NPC_KILLED,

	/** Alchemy cast on an item. value = item id. */
	ALCH,

	/**
	 * Food or drink actually consumed, confirmed by the animation rather than the click. text =
	 * "eat" or "drink", value = item id.
	 */
	CONSUMED,

	/** Food eaten while on the edge of dying. */
	CLUTCH_EAT,

	/**
	 * Any menu click, as "option|target" lowercased. Where MENU_CLICK carries only the option,
	 * this carries what was clicked as well, which is the only reliable way to identify things
	 * the game names rather than numbers, such as a specific emote.
	 */
	MENU_TARGET,

	/** A teleport was cast. value = animation id. */
	TELEPORT,

	/**
	 * Travel by a transport network completed, confirmed by the player actually moving. text is
	 * the kind, "spirittree" or "fairyring".
	 */
	TRAVEL,

	/** A server message in the chatbox. text = the message with tags stripped. */
	CHAT_GAME,

	/** A line of dialogue with the speaker stripped, lowercased. */
	CHAT_DIALOG,

	/** A public chat message the local player sent. text = the message. */
	CHAT_PUBLIC_SELF,

	/** The local player took a hit. value = damage dealt. */
	DAMAGE_TAKEN,

	/** The local player dealt a hit for no damage. */
	ZERO_HIT_DEALT,

	/** The local player landed a hit on something else. value = damage dealt. */
	DAMAGE_DEALT,

	/** A spell splashed on its target. */
	SPLASH,

	/** The local player died. */
	DEATH,

	/** Poison took hold, having not been active before. */
	POISONED,

	/** Venom took hold, having not been active before. */
	VENOMED,

	/** Prayers were switched on. value = how many, since quick prayers light several at once. */
	PRAYER_TOGGLE,

	/** One tile of movement. text = "walk" or "run", value = 1 when no boots were on. */
	TILE_WALKED,

	/** Fired once per unbroken block of standing still. */
	IDLE_PERIOD,

	/** Run energy reached zero, once per depletion. */
	RUN_EMPTY,

	/** The camera completed a full 360 degree rotation. */
	CAMERA_SPIN,

	/** The camera zoom changed and then settled. */
	CAMERA_ZOOM,

	/** An emote was played from the emote tab. text = the emote name lowercased. */
	EMOTE_USED,

	/**
	 * The Wilderness ditch was actually hopped, taken off the jump animation.
	 *
	 * <p>Counted from the animation rather than the "Cross" click, which fires the moment the
	 * player expresses an interest: clicking from across the bank counted before they arrived,
	 * cancelling still counted, and standing next to it clicking counted repeatedly.
	 */
	DITCH_CROSSED,

	/**
	 * Seeds put into a farming patch. value = how many, since an allotment takes three at once.
	 *
	 * <p>Read off the chat line rather than off Farming experience, which also pays for checking
	 * health, curing disease and composting, and would have counted all of those as farming.
	 */
	SEED_PLANTED,

	/**
	 * A special attack landed nothing at all.
	 *
	 * <p>Judged once the special has finished rather than on its first hitsplat. Claws and
	 * the other multi hit specials open with a zero often enough that calling that a miss
	 * would be wrong most of the time.
	 */
	SPEC_MISSED,

	/** An inventory item was used on another player. text = the menu target lowercased. */
	USED_ON_PLAYER,

	/** An item withdrawn that was deposited earlier in the same bank visit. value = item id. */
	BANK_YOYO,

	/** A poll vote was accepted. Once per submission, never for merely opening the booth. */
	POLL_VOTED,

	/** Prayer points reached zero, once per depletion. */
	PRAYER_EMPTY,

	/** The world map was opened. */
	WORLD_MAP_OPENED,

	/** The bank interface opened. */
	BANK_OPENED,

	/** A trade with another player opened. */
	TRADE_OPENED,

	/**
	 * A skill gained experience. text = the skill name lowercased, value = the amount gained.
	 * One event per xp drop, which is the only reliable way to count a successful gathering
	 * action: mining ore and washing pay-dirt print nothing to the chatbox.
	 */
	SKILL_XP,

	/** A special attack was used, seen as the energy bar dropping. */
	SPECIAL_ATTACK,

	/** The player hopped worlds. */
	WORLD_HOP,

	/** The player logged in. */
	LOGIN;

	/**
	 * Types a player can fire several times inside one game tick, because they come from clicking
	 * rather than from the game doing something. A task on one of these is capped at one count per
	 * tick, or the mouse rather than the game decides how fast it levels.
	 *
	 * <p>Everything absent from this set repeats for honest reasons: several hitsplats land in a
	 * tick in multi, a kill can be shared, running covers two tiles.
	 */
	private static final Set<TaskEventType> SPAMMABLE = EnumSet.of(
		MENU_CLICK, MENU_TARGET, ITEM_ACTION, OBJECT_ACTION, NPC_ACTION, PLAYER_ACTION,
		ALCH, CLUTCH_EAT, CONSUMED, CHAT_GAME, CHAT_PUBLIC_SELF, PRAYER_TOGGLE,
		BANK_OPENED, WORLD_MAP_OPENED, TRADE_OPENED, EMOTE_USED, CHAT_DIALOG, USED_ON_PLAYER, BANK_YOYO);

	public boolean isSpammable()
	{
		return SPAMMABLE.contains(this);
	}
}

