/** One line on the Stats tab: label on the left, running total on the right. */
class StatRow extends JPanel
{
	private final Stat stat;
	private final JLabel value = new JLabel("0", SwingConstants.RIGHT);

	StatRow(Stat stat)
	{
		this.stat = stat;

		setLayout(new BorderLayout(6, 0));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(BorderFactory.createEmptyBorder(3, 8, 3, 8));

		JLabel label = new JLabel(stat.getLabel());
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(Palette.MUTED);

		value.setFont(FontManager.getRunescapeSmallFont());
		value.setForeground(Color.WHITE);

		add(label, BorderLayout.CENTER);
		add(value, BorderLayout.EAST);
	}

	void update(ProgressTracker tracker)
	{
		long raw = tracker.statValue(stat);
		value.setText(stat.render(raw));
		// An untouched stat is greyed out, so the ones that have moved carry the eye.
		value.setForeground(raw == 0 ? Palette.MUTED : Color.WHITE);
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}
}

