	 * Tasks currently in the container, in order, so an unchanged list can skip the rebuild. Null
	 * until the first build, which forces one: an empty list is a real state, reached by a filter
	 * that matches nothing, and it has to be told apart from never having drawn.
	 */
	private List<Task> shownTasks;

	private final JComboBox<Filter> filterBox = new JComboBox<>(Filter.values());
	private final JComboBox<Sort> sortBox = new JComboBox<>(Sort.values());

	/** Item icons load off the client thread, so cache them rather than refetching per refresh. */
