	private final JLabel sinceValue = new JLabel("-", SwingConstants.RIGHT);

	/** Day precision. The hour Unachievements was switched on is not worth a column of the row. */
	private static final DateTimeFormatter SINCE_FORMAT =
		DateTimeFormatter.ofPattern("d MMM yyyy", Locale.ENGLISH);
	private final JPanel controlsRow = new JPanel(new BorderLayout());

	/** True while the Tasks tab is selected, false for Stats. */
	private boolean tasksTab = true;

