	private Tier shownBest;

	@Inject
	UnachievementsPanel(ItemManager itemManager)
	{
		super();
		this.itemManager = itemManager;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		for (Task task : TaskRegistry.TASKS)
		{
			rows.put(task.getId(), new TaskRow(task, this::toggleMute));
		}

		taskList.setLayout(new BoxLayout(taskList, BoxLayout.Y_AXIS));
		taskList.setBackground(ColorScheme.DARK_GRAY_COLOR);

		statList.setLayout(new BoxLayout(statList, BoxLayout.Y_AXIS));
		statList.setBackground(ColorScheme.DARK_GRAY_COLOR);
		statList.setVisible(false);
		buildStatList();

		// Header and controls go on the wrapper panel rather than on this one. PluginPanel puts
		// `this` inside a JScrollPane, so anything added here scrolls away; the wrapper sits
		// outside it and stays pinned to the top.
		JPanel pinned = new JPanel(new BorderLayout());
		pinned.setBackground(ColorScheme.DARK_GRAY_COLOR);
		pinned.setBorder(BorderFactory.createMatteBorder(0, 0, 1, 0, Palette.OUTLINE));

		JPanel controls = buildControls();
		controls.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));

