	private void toggleMute(Task task)
	{
		if (plugin == null)
		{
			return;
		}
		plugin.toggleMute(task);
		rows.get(task.getId()).update(plugin.getTracker());
	}

	/**
	 * The view switcher: the current view named in the middle, an arrow either side.
	 *
	 * <p>Replaces a pair of tabs, which read as dialog buttons parked on top of the filter row.
	 * ASCII arrows rather than the Unicode ones, which come out as fat triangles in this font.
	 * With only two views both arrows do the same thing, and that is fine: either one gets you to
	 * the other view without having to work out which way it points.
	 */
	private JPanel buildSwitcher()
	{
		viewTitle.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 14f));
		viewTitle.setForeground(Palette.PROGRESS);

		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createMatteBorder(0, 0, 1, 0, Palette.OUTLINE));
		row.add(arrow("<"), BorderLayout.WEST);
		row.add(viewTitle, BorderLayout.CENTER);
		row.add(arrow(">"), BorderLayout.EAST);
		return row;
	}

	private JButton arrow(String glyph)
	{
		JButton button = new JButton(glyph);
		button.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 14f));
		button.setForeground(Palette.MUTED);
		button.setFocusPainted(false);
		button.setBorderPainted(false);
		button.setContentAreaFilled(false);
		button.setBorder(BorderFactory.createEmptyBorder(7, 14, 6, 14));
		button.setCursor(new Cursor(Cursor.HAND_CURSOR));
		button.addActionListener(e -> selectTab(!tasksTab));

		// Swing does not bubble mouse events, so the hover tint goes on the button itself.
		button.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				button.setForeground(Palette.PROGRESS);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				button.setForeground(Palette.MUTED);
			}
		});
		return button;
	}

	private void selectTab(boolean tasks)
	{
		if (tasksTab == tasks)
		{
			return;
		}
		tasksTab = tasks;
		viewTitle.setText(tasks ? "TASKS" : "STATS");
		taskList.setVisible(tasks);
		statList.setVisible(!tasks);
		controlsRow.setVisible(tasks);
		refresh();
		revalidate();
		repaint();
	}

	/** Built once. Only the numbers change, so the rows never need rebuilding. */
	private void buildStatList()
	{
		StatCategory heading = null;
		for (Stat stat : StatRegistry.STATS)
		{
			if (stat.getCategory() != heading)
			{
				heading = stat.getCategory();
				statList.add(sectionHeading(heading.getDisplayName()));
			}
			StatRow row = new StatRow(stat);
			statRows.add(row);
			statList.add(row);
		}

		// Set apart from the last stat: it is a footnote on all of them rather than one more line
		// in the Interface section, and read as part of that section without the gap and the rule.
		statList.add(Box.createVerticalStrut(10));
		statList.add(sinceRow());
	}

	/** Footer on the Stats tab: the date every number above it counts from. */
	private JPanel sinceRow()
	{
		JLabel label = new JLabel("Data since");
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(Palette.MUTED);

		sinceValue.setFont(FontManager.getRunescapeSmallFont());
		sinceValue.setForeground(Color.WHITE);

		JPanel row = new JPanel(new BorderLayout(6, 0))
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(1, 0, 0, 0, Palette.OUTLINE),
			BorderFactory.createEmptyBorder(7, 8, 3, 8)));
		row.add(label, BorderLayout.CENTER);
		row.add(sinceValue, BorderLayout.EAST);
		return row;
	}

	/** Full width band so the text centres on the panel rather than on its own preferred size. */
	private static JPanel sectionHeading(String text)
	{
		JLabel title = new JLabel(text, SwingConstants.CENTER);
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Palette.PROGRESS);

		JPanel band = new JPanel(new BorderLayout())
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		band.setBackground(ColorScheme.DARK_GRAY_COLOR);
		band.setBorder(BorderFactory.createEmptyBorder(12, 8, 5, 8));
		band.add(title, BorderLayout.CENTER);
		return band;
	}

	private JPanel buildHeader()
	{
		JPanel header = new JPanel();
		header.setLayout(new BorderLayout(0, 6));
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setBorder(BorderFactory.createEmptyBorder(10, 8, 10, 8));

		JLabel title = new JLabel("UNACHIEVEMENTS", SwingConstants.CENTER);
		title.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 20f));
		title.setForeground(Palette.PROGRESS);
		// The 20pt glyphs sit tight against their bounds, so the helm row needs pushing clear.
		title.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));

		// Helm on the left is your overall rank; dagger on the right is your best single task.
		// Early on the dagger runs well ahead, which is the point of showing both.
		JPanel rankRow = new JPanel(new FlowLayout(FlowLayout.CENTER, 8, 0));
		rankRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		rankLabel.setFont(FontManager.getRunescapeBoldFont());
		rankRow.add(helmLabel);
		rankRow.add(rankLabel);
		rankRow.add(daggerLabel);

		JPanel top = new JPanel(new BorderLayout(0, 2));
		top.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		top.add(title, BorderLayout.NORTH);
		top.add(rankRow, BorderLayout.CENTER);

		JPanel stats = new JPanel(new GridLayout(1, 2, 8, 0));
		stats.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		stats.setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));
		stats.add(stat(levelValue, levelCaption));
		stats.add(stat(actionsValue, actionsCaption));

		JPanel bottom = new JPanel(new BorderLayout());
		bottom.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		bottom.add(rankBar, BorderLayout.NORTH);
		bottom.add(stats, BorderLayout.CENTER);

		header.add(top, BorderLayout.NORTH);
		header.add(bottom, BorderLayout.CENTER);
		return header;
	}

	/** One stat block: the number, then a small muted caption under it. */
	private static JPanel stat(JLabel value, JLabel caption)
	{
		value.setFont(FontManager.getRunescapeBoldFont());
		value.setForeground(Color.WHITE);
		value.setHorizontalAlignment(SwingConstants.CENTER);

		caption.setFont(FontManager.getRunescapeSmallFont());
		caption.setForeground(Palette.MUTED);
		caption.setHorizontalAlignment(SwingConstants.CENTER);

		JPanel block = new JPanel(new BorderLayout(0, 1));
		block.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		block.add(value, BorderLayout.NORTH);
		block.add(caption, BorderLayout.CENTER);
		return block;
	}

	private JPanel buildControls()
	{
		JPanel controls = new JPanel(new BorderLayout(6, 0));
		controls.setBackground(ColorScheme.DARK_GRAY_COLOR);

		controls.add(labelled("Filter", filterBox, SwingConstants.LEFT), BorderLayout.WEST);
		controls.add(labelled("Sort", sortBox, SwingConstants.RIGHT), BorderLayout.EAST);

		filterBox.addActionListener(e -> rebuildList());
		sortBox.addActionListener(e -> rebuildList());

		return controls;
	}

	private JPanel labelled(String text, JComboBox<?> box, int alignment)
	{
		JLabel label = new JLabel(text, alignment);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(Palette.MUTED);

		box.setFont(FontManager.getRunescapeSmallFont());
		box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		box.setForeground(Color.WHITE);
		box.setFocusable(false);
		box.setPreferredSize(new Dimension(92, 22));
		box.setRenderer(new DefaultListCellRenderer()
		{
			@Override
			public void setHorizontalAlignment(int ignored)
			{
				super.setHorizontalAlignment(alignment);
			}
		});

		JPanel wrapper = new JPanel(new BorderLayout(0, 2));
		wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrapper.add(label, BorderLayout.NORTH);
		wrapper.add(box, BorderLayout.CENTER);
		return wrapper;
	}

	private JPanel buildFooter()
	{
		JPanel footer = new JPanel(new BorderLayout());
		footer.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JButton reset = new JButton("Reset progress");
		reset.setFont(FontManager.getRunescapeSmallFont());
		reset.setFocusPainted(false);
		reset.setToolTipText("Clears all progress for this account.");
		reset.addActionListener(e ->
		{
			int choice = JOptionPane.showConfirmDialog(this,
				"Erase all Unachievements progress for this account?",
				"Reset progress", JOptionPane.YES_NO_OPTION);
			if (choice == JOptionPane.YES_OPTION && plugin != null)
			{
				plugin.resetProgress();
			}
		});

		footer.add(reset, BorderLayout.CENTER);
		return footer;
	}

	/** Safe to call from any thread. */
	void refresh()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::refresh);
			return;
		}
		if (plugin == null)
		{
			return;
		}

		ProgressTracker tracker = plugin.getTracker();
		Tier rank = tracker.getRank();
		Tier best = tracker.getBestTier();

		rankLabel.setText(rank.getDisplayName());
		rankLabel.setForeground(Color.WHITE);
		setIcon(helmLabel, helms, rank, shownRank, Tier::getHelmItemId);
		setIcon(daggerLabel, daggers, best, shownBest, Tier::getDaggerItemId);
		shownRank = rank;
		shownBest = best;

		float mean = tracker.getMeanLevel();
		rankBar.set(mean, rank);
		describeRank(rank, best, mean);

		levelValue.setText(String.format("%,d", tracker.getTotalLevel()));
		levelCaption.setText("Total Level");

		actionsValue.setText(String.format("%,d", tracker.getTotalActions()));
		actionsCaption.setText("Total Actions");

		if (!tasksTab)
		{
			for (StatRow row : statRows)
			{
				row.update(tracker);
			}
			long since = tracker.getTrackingSince();
			sinceValue.setText(since <= 0 ? "-"
				: SINCE_FORMAT.format(Instant.ofEpochMilli(since).atZone(ZoneId.systemDefault())));
			return;
		}

		for (Task task : TaskRegistry.TASKS)
		{
			rows.get(task.getId()).update(tracker);
		}

		rebuildList();
	}

	/**
	 * Names the three things in the header that carry no label of their own. Two tier icons either
	 * side of one word, measuring different things, and a bar with a bare percentage on it.
	 */
	private void describeRank(Tier rank, Tier best, float mean)
	{
		helmLabel.setToolTipText("<html><b>Overall rank:</b> " + rank.getDisplayName() + "</html>");
		daggerLabel.setToolTipText("<html><b>Highest task:</b> " + best.getDisplayName() + "</html>");

		Tier next = rank.next();
		String level = String.format("%.1f", mean)
			+ (next == null ? "" : "/" + next.getLevelRequirement());
		rankBar.setToolTipText("<html><b>Average Level:</b> " + level + "</html>");
	}

	private void setIcon(JLabel label, Map<Tier, AsyncBufferedImage> cache, Tier tier, Tier shown,
		java.util.function.ToIntFunction<Tier> itemId)
	{
		if (tier == shown)
		{
			return;
		}
		AsyncBufferedImage image = cache.computeIfAbsent(tier,
			t -> itemManager.getImage(itemId.applyAsInt(t)));
		label.setIcon(null);
		image.addTo(label);
	}

	/** Applies the filter and sort selections. Cheap enough to redo whenever a count moves. */
	private void rebuildList()
	{
		if (plugin == null)
		{
			return;
		}

		ProgressTracker tracker = plugin.getTracker();
		Filter filter = (Filter) filterBox.getSelectedItem();
		Sort sort = (Sort) sortBox.getSelectedItem();

		List<Task> visible = new ArrayList<>();
		for (Task task : TaskRegistry.TASKS)
		{
			if (matches(filter, tracker, task))
			{
				visible.add(task);
			}
		}

		visible.sort(comparator(sort, tracker));

		// The rows have already refreshed themselves; all that is left is the container, and the
		// membership and order behind it usually have not moved. Comparing the computed list is
		// safe by construction: any filter, sort or underlying value change produces a different
		// one. Skipping saves tearing down and rebuilding every row, plus a fresh strut each,
		// once a tick for a list that looks identical.
		if (visible.equals(shownTasks))
		{
			return;
		}
		shownTasks = visible;

		taskList.removeAll();
		for (Task task : visible)
		{
			taskList.add(rows.get(task.getId()));
			taskList.add(Box.createVerticalStrut(3));
		}

		if (visible.isEmpty())
		{
			JLabel empty = new JLabel("Nothing matches that filter.", SwingConstants.CENTER);
			empty.setFont(FontManager.getRunescapeSmallFont());
			empty.setForeground(Palette.MUTED);
			empty.setBorder(BorderFactory.createEmptyBorder(12, 0, 12, 0));
			taskList.add(empty);
		}

		taskList.revalidate();
		taskList.repaint();
	}

	private static boolean matches(Filter filter, ProgressTracker tracker, Task task)
	{
		int count = tracker.getCount(task);
		int level = tracker.getLevel(task);
		switch (filter)
		{
			case IN_PROGRESS:
				return count > 0 && level < XpTable.MAX_LEVEL;
			case UNTOUCHED:
				return count == 0;
			case MAXED:
				return level >= XpTable.MAX_LEVEL;
			case ALL:
			default:
				return true;
		}
	}

	private static Comparator<Task> comparator(Sort sort, ProgressTracker tracker)
	{
		switch (sort)
		{
			case RECENT:
				// Never touched sorts to zero, so untouched tasks collect at the bottom in
				// registry order rather than scattering through the list.
				return Comparator.comparingLong((Task t) -> tracker.getLastUpdated(t)).reversed();
			case NAME:
				return Comparator.comparing(Task::getName);
			case COUNT:
				return Comparator.comparingInt((Task t) -> tracker.getCount(t)).reversed();
			case PROGRESS:
				return Comparator.comparingDouble((Task t) -> tracker.getProgress(t)).reversed();
			case LEVEL:
			default:
				// Highest level first, then whoever is furthest into the next one.
				return Comparator.comparingInt((Task t) -> tracker.getLevel(t))
					.thenComparingDouble(t -> tracker.getProgress(t))
					.reversed();
		}
	}

	/**
	 * Overall rank progress, measured in mean task level so it self scales as tasks are added.
	 * Fills across the current rank band only, emptying and refilling at every promotion.
	 */
	private static class RankBar extends JPanel
	{
		private static final int HEIGHT = 22;

		private static final Color TROUGH = new Color(0x141210);
		private static final Color FILL_TOP = new Color(0xFFB042);
		private static final Color FILL_BOTTOM = new Color(0xD97C06);
		private static final Color FILL_HIGHLIGHT = new Color(0xFFD79A);

		private Tier rank = Tier.BRONZE;
		private float fraction;
		private String text = "";

		RankBar()
		{
			setPreferredSize(new Dimension(0, HEIGHT));
			setMinimumSize(new Dimension(0, HEIGHT));
			setBackground(ColorScheme.DARKER_GRAY_COLOR);
		}

		void set(float meanLevel, Tier rank)
		{
			this.rank = rank;
			Tier next = rank.next();

			if (next == null)
			{
				fraction = 1f;
				text = rank.getDisplayName().toUpperCase();
			}
			else
			{
				int floor = rank.getLevelRequirement();
				int ceiling = next.getLevelRequirement();
				fraction = Math.max(0f, Math.min(1f, (meanLevel - floor) / (ceiling - floor)));
				text = Math.min(99, (int) (fraction * 100)) + "%";
			}

			repaint();
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			super.paintComponent(graphics);

			Graphics2D g = (Graphics2D) graphics.create();
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);

			int w = getWidth();
			int h = HEIGHT;
			int inner = w - 2;

			g.setColor(TROUGH);
			g.fillRect(1, 1, inner, h - 2);

			int fill = Math.round(inner * fraction);
			if (fill > 0)
			{
				g.setPaint(new GradientPaint(0, 1, FILL_TOP, 0, h - 1, FILL_BOTTOM));
				g.fillRect(1, 1, fill, h - 2);
				g.setPaint(null);
				g.setColor(FILL_HIGHLIGHT);
				g.drawLine(1, 1, fill, 1);
			}

			g.setColor(Palette.OUTLINE);
			g.drawRect(0, 0, w - 1, h - 1);

			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
				RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			g.setFont(FontManager.getRunescapeSmallFont());
			FontMetrics fm = g.getFontMetrics();
			int tx = (w - fm.stringWidth(text)) / 2;
			int ty = (h + fm.getAscent()) / 2 - 1;
			g.setColor(Color.BLACK);
			g.drawString(text, tx + 1, ty + 1);
			g.setColor(Color.WHITE);
			g.drawString(text, tx, ty);

			g.dispose();
		}
	}
}

package com.tommyknight.unachievements;

import java.awt.Color;

/**
 * Shared sidebar colours.
 *
 * <p>Progress bars are deliberately one colour everywhere rather than tinted per tier. Tier
 * identity is already carried by the row background and the tier label, and colouring the bars
 * too left the panel looking like four unrelated widgets.
 */
final class Palette
{
	/** Fill for every progress bar, header and row alike. The game's interface orange. */
	static final Color PROGRESS = new Color(0xFF981F);

	/** Empty part of a progress bar. */
	static final Color TROUGH = new Color(0x1E1E1E);

	/** Outer line on bevelled elements, matching the popup. */
	static final Color OUTLINE = new Color(0x241F18);

	static final Color MUTED = new Color(140, 137, 132);

	private Palette()
	{
	}
}
